                              <Icons.Store className="w-5 h-5" /> <span className="font-bold tracking-wide">Store</span>
                          </button>

                          {/* Get More - Premium Deep Blue */}
                          <button onClick={() => { sounds.playClick(); onOpenDiamondShop(); }} className="w-full p-4 btn-premium-deep text-white rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md overflow-hidden relative">
                              <span className="font-bold tracking-wide relative z-10">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10" />
                          </button>
                      </div>

                      {/* Row 2: Stats & Bonus - 300ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down"
                        style={{ animationDelay: '300ms' }}
                      >
                          {/* Stats - Blue */}
                          <button onClick={() => { sounds.playClick(); onOpenStats(); }} className="w-full p-4 bg-blue-100 dark:bg-blue-900/40 text-blue-900 dark:text-blue-100 border border-blue-200 dark:border-blue-800 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md">
                              <Icons.BarChart className="w-5 h-5" /> <span className="font-bold tracking-wide">Stats</span>
                          </button>

                          {/* Daily Bonus - Green */}
                          <button 
                              onClick={onClaimBonus} 
                              disabled={!!timeLeft}
                              className={`w-full p-4 border rounded-2xl shadow-sm flex items-center justify-center gap-2 transition overflow-hidden relative ${
                                  !!timeLeft 
                                  ? 'bg-t-surface-sec border-t-border text-t-secondary cursor-not-allowed' 
                                  : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-900 dark:text-emerald-100 border-emerald-200 dark:border-emerald-800 hover:shadow-md active:scale-95'
                              }`}
                          >
                              {!!timeLeft ? (
