                <div className="w-full max-w-md pt-2">

                    {/* Collapsible Difficulty Menu (Accordion Style) */}
                    <div className="w-full mb-6 z-20">
                        <button 
                            onClick={handleToggleMenu}
                            className="w-full bg-t-surface p-4 rounded-2xl shadow-sm border border-t-border flex items-center justify-between active:scale-[0.98] transition-all relative z-10"
