import React, { useRef, useState, useEffect } from 'react';
import { Icons } from './Icons';

interface UnlockCardProps {
    startLevel: number;
    endLevel: number;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

export const UnlockCard: React.FC<UnlockCardProps> = ({ startLevel, endLevel, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);
    const [showUnlockUI, setShowUnlockUI] = useState(false);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                    setShowUnlockUI(false); // Reset UI state
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            const duration = 2500; // Slower duration
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = progress; // Linear easing

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                    if (rawPercent === 100) {
                        // Wait a moment after hitting 100% before showing the unlock button
                        setTimeout(() => {
                            setShowUnlockUI(true);
                        }, 500);
                    }
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!showUnlockUI) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-6 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!showUnlockUI}
                className={`w-full h-32 rounded-[1.5rem] relative overflow-hidden transition-all duration-500 ease-out group ${
                    showUnlockUI 
                        ? 'bg-gradient-to-b from-white to-blue-50/50 dark:from-stone-800 dark:to-stone-900 shadow-lg active:scale-[0.98] border border-blue-100 dark:border-blue-900/30 cursor-pointer' 
                        : 'bg-stone-200 dark:bg-stone-800/80 cursor-default border border-transparent'
                }`}
            >
                {/* Background Decor for Unlock State */}
                {showUnlockUI && (
                    <div className="absolute inset-0 opacity-100 pointer-events-none">
                        <div className="absolute -top-12 -right-12 w-32 h-32 bg-blue-400/10 rounded-full blur-2xl"></div>
                        <div className="absolute -bottom-12 -left-12 w-32 h-32 bg-indigo-400/10 rounded-full blur-2xl"></div>
                    </div>
                )}

                {/* Content Container */}
                <div className="absolute inset-0 flex items-center justify-center px-6">
                    {showUnlockUI ? (
                        <div className="flex flex-row items-center justify-between w-full animate-fade-in relative z-10 gap-2">

                             {/* Left Side: Info & CTA */}
                             <div className="flex flex-col items-start gap-1.5">
                                 {/* Header Pill */}
                                 <div className="flex items-center gap-1.5 px-2.5 py-1 bg-white dark:bg-stone-800 rounded-full shadow-sm border border-stone-100 dark:border-stone-700">
                                    <Icons.LockOpen className="w-3 h-3 text-blue-500" />
                                    <span className="text-[10px] font-bold text-stone-500 dark:text-stone-400 uppercase tracking-widest pt-0.5">
                                        Levels {startLevel}-{endLevel}
                                    </span>
                                 </div>
                                 {/* Flashing CTA */}
                                 <span className="text-[10px] font-bold text-blue-500 uppercase tracking-widest pl-1 animate-pulse ml-0.5">
                                     Tap to Unlock
                                 </span>
                             </div>

                             {/* Right Side: Price */}
                             <div className="flex items-center gap-2">
                                <span className="text-5xl font-bold text-stone-900 dark:text-white leading-none">
                                    {cost}
                                </span>
                                <Icons.Diamond className="w-8 h-8 text-blue-500 fill-current drop-shadow-sm" />
                             </div>
                        </div>
                    ) : (
                        <div className="flex flex-row items-center justify-between w-full gap-5">
                            {/* Left Side: Lock Icon */}
                            <div className="w-14 h-14 rounded-xl bg-stone-300/50 dark:bg-stone-700/50 flex items-center justify-center shadow-inner">
                                <Icons.Lock className="w-6 h-6 text-stone-500 dark:text-stone-400" />
                            </div>

                            {/* Right Side: Progress Stats */}
                            <div className="flex-1 flex flex-col items-start gap-2">
                                <div className="flex items-baseline gap-1.5">
                                    <span className="text-3xl font-bold text-stone-500 dark:text-stone-400 leading-none">
                                        {animatedPercent}
                                    </span>
                                    <span className="text-lg font-bold text-stone-400 dark:text-stone-500">%</span>
                                </div>
                                {/* Modern Progress Bar */}
                                <div className="w-full h-2.5 bg-stone-300 dark:bg-stone-700 rounded-full overflow-hidden p-[1px]">
                                    <div 
                                        className="h-full bg-loading-green rounded-full shadow-sm transition-all duration-200 ease-out" 
                                        style={{ width: `${animatedPercent}%` }}
                                    />
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { Logo } from '../ui/Logo';
import { sounds } from '../../utils/sound';
import { getDifficultyPoints, DIFFICULTY_DESCRIPTIONS } from '../../utils/constants';

interface DifficultyScreenProps {
    points: number;
    onDifficultySelect: (diff: Difficulty) => void;
    onOpenSettings: () => void;
    onOpenStore: () => void;
    onOpenDiamondShop: () => void;
    onClaimBonus: () => void;
    onOpenStats: () => void;
    nextBonusClaimTime: number;
}

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore, 
    onOpenDiamondShop, 
    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");
    const [activeInfo, setActiveInfo] = useState<Difficulty | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    // Track index for cycling descriptions per difficulty
    const [infoIndices, setInfoIndices] = useState<Record<string, number>>({});

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            const diff = nextBonusClaimTime - now;
            const h = Math.floor(diff / (1000 * 60 * 60));
            const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((diff % (1000 * 60)) / 1000);

            // Pad with leading zeros
            const hStr = h.toString().padStart(2, '0');
            const mStr = m.toString().padStart(2, '0');
            const sStr = s.toString().padStart(2, '0');

            setTimeLeft(`${hStr}:${mStr}:${sStr}`);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            // Cycle to the next description after closing
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
            }));
        }, 150); // Matches tooltip-exit duration
    };

    const handleInfoToggle = (diff: Difficulty) => {
        sounds.playTap();
        if (activeInfo === diff) {
            handleClose();
        } else {
            setActiveInfo(diff);
            setIsClosing(false);
        }
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => activeInfo && handleClose()}
        >
             {/* Scrollable Content - No Fixed Header */}
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">

                  {/* Hero Section - Static (Always on screen) */}
                  <div className="flex flex-col items-center mt-[70px] mb-6">
                      <Logo size={70} className="mb-4 drop-shadow-xl" />
                      <h1 className="text-3xl font-semibold text-t-primary mb-2 tracking-tight">Oku</h1>
                      <div className="h-px w-12 bg-t-border mb-3"></div>
                  </div>

                  {/* Difficulty Header - Stagger Step 1 (50ms) */}
                  <div 
                    className="w-full max-w-md flex justify-center mb-2 opacity-0 animate-slide-in-down" 
                    style={{ animationDelay: '50ms' }}
                  >
                      <p className="text-xs font-semibold text-t-secondary uppercase tracking-[0.2em]">Choose your pace</p>
                  </div>

                  {/* Difficulty Grid - Stagger Steps 2, 3, 4 (Row based) */}
                  <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-8 shrink-0">
                      {Object.values(Difficulty).map((diff, index) => {
                          const completed = Storage.getCompletedCount(diff, 300);
                          const isPack2Unlocked = Storage.isPack2Unlocked(diff);
                          const isPack3Unlocked = Storage.isPack3Unlocked(diff);

                          // Get cycling description
                          const descriptions = DIFFICULTY_DESCRIPTIONS[diff];
                          const currentIndex = infoIndices[diff] || 0;
                          const description = descriptions[currentIndex % descriptions.length];

                          let maxLevels = 100;
                          if (isPack2Unlocked) maxLevels = 200;
                          if (isPack3Unlocked) maxLevels = 300;

                          const diffPoints = getDifficultyPoints(diff);

                          // Calculate staggered delay based on row index (0, 1, 2)
                          // Base start 100ms, each row adds 50ms
                          const row = Math.floor(index / 2);
                          const delay = 100 + (row * 50);

                          const isInfoActive = activeInfo === diff;
                          const isLeftColumn = index % 2 === 0;

                          return (
                              <button 
                                key={diff} 
                                onClick={() => onDifficultySelect(diff)} 
                                style={{ animationDelay: `${delay}ms` }}
                                className={`bg-t-surface p-3 rounded-2xl shadow-sm border border-t-border flex flex-col justify-between active:scale-95 transition-all text-left relative group opacity-0 animate-slide-in-down min-h-[100px] ${isInfoActive ? 'z-[100]' : 'z-0'}`}
                              >
                                  {/* Header: Title & Points */}
                                  <div className="w-full flex justify-between items-center mb-1">
                                      <span className="text-lg font-semibold text-t-primary leading-none tracking-tight">{diff}</span>
                                      <div className="flex items-center gap-1 shrink-0">
                                          <span className="text-sm font-bold text-t-primary">+{diffPoints}</span>
                                          <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                                      </div>
                                  </div>

                                  {/* Middle: Info & Progress Numbers */}
                                  <div className="w-full flex justify-between items-end mb-1.5 mt-auto">
                                      {/* Info Icon */}
                                      <div className="relative z-30" onClick={(e) => e.stopPropagation()}>
                                            <div 
                                                role="button"
                                                onClick={() => handleInfoToggle(diff)}
                                                className={`w-[24px] h-[24px] rounded-full border flex items-center justify-center transition-colors cursor-pointer ${
                                                    isInfoActive 
                                                    ? 'bg-stone-200 border-stone-400 dark:bg-stone-600 dark:border-stone-400' 
                                                    : 'border-stone-300 dark:border-stone-600 bg-t-surface hover:bg-stone-100 dark:hover:bg-stone-700'
                                                }`}
                                            >
                                                <Icons.Info className={`w-3.5 h-3.5 ${isInfoActive ? 'text-stone-700 dark:text-stone-200' : 'text-stone-400 dark:text-stone-500'}`} />
                                            </div>

                                            {/* Tooltip */}
                                            {isInfoActive && (
                                                <div 
                                                    className={`absolute top-full mt-2 w-44 z-[100] cursor-default ${
                                                        isLeftColumn 
                                                            ? 'left-0 origin-top-left' 
                                                            : 'right-0 origin-top-right'
                                                    } ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}
                                                    onClick={(e) => e.stopPropagation()}
                                                >
                                                    <div className="filter drop-shadow-[0_8px_16px_rgba(0,0,0,0.25)]">
                                                        <div className="bg-white text-stone-900 text-xs font-medium p-3 rounded-xl relative text-left leading-relaxed">
                                                            {description}
                                                            <div className={`absolute -top-[6px] w-3 h-3 bg-white transform rotate-45 ${
                                                                isLeftColumn ? 'left-[6px]' : 'right-[6px]'
                                                            }`}></div>
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                      </div>

                                      {/* Progress Numbers */}
                                      <span className="text-base text-t-primary font-semibold tracking-wide font-sans leading-none">{completed} / {maxLevels}</span>
                                  </div>

                                  {/* Bottom: Progress Bar */}
                                  <div className="w-full h-1.5 bg-t-surface-sec rounded-full overflow-hidden">
                                      <div className="h-full bg-loading-blue" style={{ width: `${Math.min((completed/maxLevels)*100, 100)}%` }}></div>
                                  </div>
                              </button>
                          )
                      })}
                  </div>

                  {/* Footer Actions - Stagger Steps 5, 6 */}
                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      {/* Row 1: Store & Get More - 250ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down" 
                        style={{ animationDelay: '250ms' }}
                      >
                          {/* Store - Gold */}
                          <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStore(); }} className="w-full p-4 bg-[#FFF9C4] dark:bg-amber-900/40 text-amber-900 dark:text-amber-100 border border-amber-200 dark:border-amber-800 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition relative hover:shadow-md">
                              <Icons.Store className="w-5 h-5" /> <span className="font-semibold tracking-wide">Store</span>
                          </button>

                          {/* Get More - Premium Deep Blue */}
                          <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenDiamondShop(); }} className="w-full p-4 btn-premium-deep text-white rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md overflow-hidden relative">
                              <span className="font-semibold tracking-wide relative z-10">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10" />
                          </button>
                      </div>

                      {/* Row 2: Stats & Bonus - 300ms */}
                      <div 
