                      >
                          {/* Stats - Blue */}
                          <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStats(); }} className="w-full p-4 bg-blue-100 dark:bg-blue-900/40 text-blue-900 dark:text-blue-100 border border-blue-200 dark:border-blue-800 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md">
                              <Icons.BarChart className="w-5 h-5" /> <span className="font-semibold tracking-wide">Stats</span>
                          </button>

                          {/* Daily Bonus - Green */}
                          <button 
                              onClick={(e) => { e.stopPropagation(); onClaimBonus(); }}
