interface DifficultyScreenProps {
    points: number;
    onDifficultySelect: (diff: Difficulty) => void;
    onOpenSettings: () => void;
    onOpenStore: () => void;
    onOpenDiamondShop: () => void;
    onClaimBonus: () => void;
    onOpenStats: () => void;
    nextBonusClaimTime: number;
}

// Internal Hook for Counting Animation
const useAnimatedCounter = (target: number, duration: number = 500) => {
    const [count, setCount] = useState(0);

    useEffect(() => {
        let startTime: number | null = null;
        let animationFrameId: number;

        // Reset start value to 0 on target change to trigger animation
        setCount(0);

        const animate = (currentTime: number) => {
            if (!startTime) startTime = currentTime;
            const progress = Math.min((currentTime - startTime) / duration, 1);

            // Cubic Ease Out
            const ease = 1 - Math.pow(1 - progress, 3);

            setCount(Math.floor(target * ease));

            if (progress < 1) {
                animationFrameId = requestAnimationFrame(animate);
            } else {
                setCount(target);
            }
        };

        animationFrameId = requestAnimationFrame(animate);

        return () => {
            if (animationFrameId) cancelAnimationFrame(animationFrameId);
        };
    }, [target, duration]);

    return count;
};

// Sub-component for individual cards
const DifficultyCard: React.FC<{
    diff: Difficulty;
    index: number;
    onSelect: (diff: Difficulty) => void;
    activeInfo: Difficulty | null;
    onInfoToggle: (diff: Difficulty) => void;
    isClosing: boolean;
    description: string;
}> = ({ diff, index, onSelect, activeInfo, onInfoToggle, isClosing, description }) => {

    // Data Loading
    const completed = Storage.getCompletedCount(diff, 300);
    const isPack2Unlocked = Storage.isPack2Unlocked(diff);
    const isPack3Unlocked = Storage.isPack3Unlocked(diff);

    let maxLevels = 100;
    if (isPack2Unlocked) maxLevels = 200;
    if (isPack3Unlocked) maxLevels = 300;

    const diffPoints = getDifficultyPoints(diff);

    // Animation Logic
    const row = Math.floor(index / 2);
    const delay = 100 + (row * 50);
    const isInfoActive = activeInfo === diff;
    const isLeftColumn = index % 2 === 0;

    // Use animated counter hook
    const animatedCompleted = useAnimatedCounter(completed, 500);

    // Calculate width percentage based on animated value for synced bar/text
    const progressPercent = Math.min((animatedCompleted / maxLevels) * 100, 100);

    return (
        <button 
            onClick={() => onSelect(diff)} 
            style={{ animationDelay: `${delay}ms` }}
            className={`bg-t-surface p-3 rounded-2xl shadow-sm border border-t-border flex flex-col justify-between active:scale-95 transition-all text-left relative group opacity-0 animate-slide-in-down min-h-[100px] ${isInfoActive ? 'z-[100]' : 'z-0'}`}
        >
            {/* Header: Title & Points */}
            <div className="w-full flex justify-between items-center mb-1">
                <span className="text-lg font-semibold text-t-primary leading-none tracking-tight">{diff}</span>
                <div className="flex items-center gap-1 shrink-0">
                    <span className="text-sm font-bold text-t-primary">+{diffPoints}</span>
                    <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                </div>
            </div>

            {/* Middle: Info & Progress Numbers */}
            <div className="w-full flex justify-between items-end mb-1.5 mt-auto">
                {/* Info Icon */}
                <div className="relative z-30" onClick={(e) => e.stopPropagation()}>
                    <div 
                        role="button"
                        onClick={() => onInfoToggle(diff)}
                        className={`w-[24px] h-[24px] rounded-full border flex items-center justify-center transition-colors cursor-pointer ${
                            isInfoActive 
                            ? 'bg-stone-200 border-stone-400 dark:bg-stone-600 dark:border-stone-400' 
                            : 'border-stone-300 dark:border-stone-600 bg-t-surface hover:bg-stone-100 dark:hover:bg-stone-700'
                        }`}
                    >
                        <Icons.Info className={`w-3.5 h-3.5 ${isInfoActive ? 'text-stone-700 dark:text-stone-200' : 'text-stone-400 dark:text-stone-500'}`} />
                    </div>

                    {/* Tooltip */}
                    {isInfoActive && (
                        <div 
                            className={`absolute top-full mt-2 w-44 z-[100] cursor-default ${
                                isLeftColumn 
                                    ? 'left-0 origin-top-left' 
                                    : 'right-0 origin-top-right'
                            } ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="filter drop-shadow-[0_8px_16px_rgba(0,0,0,0.25)]">
                                <div className="bg-white text-stone-900 text-xs font-medium p-3 rounded-xl relative text-left leading-relaxed">
                                    {description}
                                    <div className={`absolute -top-[6px] w-3 h-3 bg-white transform rotate-45 ${
                                        isLeftColumn ? 'left-[6px]' : 'right-[6px]'
                                    }`}></div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Progress Numbers (Animated) */}
                <span className="text-base text-t-primary font-semibold tracking-wide font-sans leading-none">
                    {animatedCompleted} / {maxLevels}
                </span>
            </div>

            {/* Bottom: Progress Bar (Animated) */}
            <div className="w-full h-1.5 bg-t-surface-sec rounded-full overflow-hidden">
                <div 
                    className="h-full bg-loading-blue" 
                    style={{ 
                        width: `${progressPercent}%`,
                        // Use CSS transition for extra smoothness if state updates are coarse
                        transition: 'width 0.1s linear' 
                    }}
                ></div>
            </div>
        </button>
    );
};

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore, 
    onOpenDiamondShop, 
    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");
    const [activeInfo, setActiveInfo] = useState<Difficulty | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    // Track index for cycling descriptions per difficulty
    const [infoIndices, setInfoIndices] = useState<Record<string, number>>({});

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            const diff = nextBonusClaimTime - now;
            const h = Math.floor(diff / (1000 * 60 * 60));
            const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((diff % (1000 * 60)) / 1000);

            // Pad with leading zeros
            const hStr = h.toString().padStart(2, '0');
            const mStr = m.toString().padStart(2, '0');
            const sStr = s.toString().padStart(2, '0');

            setTimeLeft(`${hStr}:${mStr}:${sStr}`);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            // Cycle to the next description after closing
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
            }));
        }, 150); // Matches tooltip-exit duration
    };

    const handleInfoToggle = (diff: Difficulty) => {
        sounds.playTap();
        if (activeInfo === diff) {
            handleClose();
        } else {
            setActiveInfo(diff);
            setIsClosing(false);
        }
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => activeInfo && handleClose()}
        >
             {/* Scrollable Content - No Fixed Header */}
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">

                  {/* Hero Section - Static (Always on screen) */}
                  <div className="flex flex-col items-center mt-[70px] mb-6">
                      <Logo size={70} className="mb-4 drop-shadow-xl" />
                      <h1 className="text-3xl font-semibold text-t-primary mb-2 tracking-tight">Oku</h1>
                      <div className="h-px w-12 bg-t-border mb-3"></div>
                  </div>

                  {/* Difficulty Header - Stagger Step 1 (50ms) */}
                  <div 
                    className="w-full max-w-md flex justify-center mb-2 opacity-0 animate-slide-in-down" 
                    style={{ animationDelay: '50ms' }}
                  >
                      <p className="text-xs font-semibold text-t-secondary uppercase tracking-[0.2em]">Choose your pace</p>
                  </div>

                  {/* Difficulty Grid - Stagger Steps 2, 3, 4 (Row based) */}
                  <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-8 shrink-0">
                      {Object.values(Difficulty).map((diff, index) => {
                          // Get cycling description logic here to pass down
                          const descriptions = DIFFICULTY_DESCRIPTIONS[diff];
                          const currentIndex = infoIndices[diff] || 0;
                          const description = descriptions[currentIndex % descriptions.length];

                          return (
                              <DifficultyCard 
                                  key={diff}
                                  diff={diff}
                                  index={index}
                                  onSelect={onDifficultySelect}
                                  activeInfo={activeInfo}
                                  onInfoToggle={handleInfoToggle}
                                  isClosing={isClosing && activeInfo === diff}
                                  description={description}
                              />
                          );
                      })}
                  </div>

                  {/* Footer Actions - Stagger Steps 5, 6 */}
                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      {/* Row 1: Store & Get More - 250ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down" 
                        style={{ animationDelay: '250ms' }}
