            className={`bg-t-surface p-3 rounded-2xl shadow-sm border border-t-border flex flex-col justify-between active:scale-95 transition-all text-left relative group opacity-0 animate-slide-in-down min-h-[100px] overflow-visible ${isInfoActive ? 'z-[100]' : 'z-0'}`}
