    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");
    const [activeInfo, setActiveInfo] = useState<Difficulty | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    // Track index for cycling descriptions per difficulty
    const [infoIndices, setInfoIndices] = useState<Record<string, number>>({});

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            const diff = nextBonusClaimTime - now;
            const h = Math.floor(diff / (1000 * 60 * 60));
            const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((diff % (1000 * 60)) / 1000);

            // Pad with leading zeros
            const hStr = h.toString().padStart(2, '0');
            const mStr = m.toString().padStart(2, '0');
            const sStr = s.toString().padStart(2, '0');

            setTimeLeft(`${hStr}:${mStr}:${sStr}`);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            // Cycle to the next description after closing
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
            }));
        }, 150); // Matches tooltip-exit duration
    };

    const handleInfoToggle = (diff: Difficulty) => {
        sounds.playTap();
        if (activeInfo === diff) {
            handleClose();
        } else {
            setActiveInfo(diff);
            setIsClosing(false);
        }
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => activeInfo && handleClose()}
        >
             {/* Scrollable Content - No Fixed Header */}
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">

                  {/* Hero Section - Static (Always on screen) */}
                  <div className="flex flex-col items-center mt-[70px] mb-6">
