                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStore(); }} 
                            style={{ background: 'linear-gradient(135deg, #E8BA6E 0%, #B78B4D 100%)' }}
                            className="w-full p-4 text-[#3f2e18] rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition relative hover:shadow-md border border-white/20"
                          >
                              <Icons.Store className="w-5 h-5" /> <span className="font-semibold tracking-wide">Store</span>
                          </button>

                          {/* Get More - Shiny Silver Gradient (#F0F0F0 -> #C0C0C0) */}
