                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);

                                  return (
                                      <button 
                                          key={skill.id}
                                          onClick={(e) => handleSkillInteraction(e, skill)}
                                          className={`w-full p-3 rounded-3xl shadow-sm border border-t-border flex items-center gap-3.5 text-left active:scale-[0.98] transition-all bg-t-surface relative overflow-hidden group`}
                                      >
                                          {/* Icon Box - Smaller */}
                                          <div className={`w-14 h-14 rounded-xl flex items-center justify-center shrink-0 ${skill.bgClass} transition-transform group-active:scale-95`}>
                                              <skill.icon className={`w-7 h-7 ${skill.class}`} />
