                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-blue-500' : 'text-t-secondary'}`}>{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-2">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1.5">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-[3px] ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-blue-500' : 'text-t-secondary'}`}>{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1.5 relative">
                                      <button 
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-[3px] ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-20 dark:opacity-30`} />
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>
                                      <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-blue-500' : 'text-t-secondary'}`}>{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1.5">
                                      <button 
                                          onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} 
                                          className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 border-[3px] ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border bg-t-surface'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center w-full ${num.bgClass}`}>
                                              <span className={`text-2xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={num.cost} />
                                      </button>
                                      <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-blue-500' : 'text-t-secondary'}`}>{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

