                                              className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-[3px] ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
