interface UseGameSkillsProps {
    board: Board;
    setBoard: Dispatch<SetStateAction<Board>>;
    solvedBoard: number[][];
    setHistory: Dispatch<SetStateAction<Board[]>>;
    moveLog: React.MutableRefObject<{r: number, c: number, v: number, t: number}[]>;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    settings: AppSettings;
    difficulty: Difficulty;
    removeNotesFromPeers: (board: Board, r: number, c: number, val: number) => void;
    checkCompletion: (board: Board) => void;
    onSaveProgress: (board: Board, scanUses?: number, revealUses?: number, focusUses?: number) => void;
    onSectionComplete?: (sections: string[]) => void;
}

const checkSectionCompletion = (board: Board, solvedBoard: number[][], r: number, c: number) => {
    const sections: string[] = [];
    // Row
    if (board[r].every((cell, idx) => cell.value === solvedBoard[r][idx])) sections.push(`row-${r}`);
    // Col
    if (board.every((row, idx) => row[c].value === solvedBoard[idx][c])) sections.push(`col-${c}`);
    // Box
    const startR = Math.floor(r/3)*3;
    const startC = Math.floor(c/3)*3;
    const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
    let boxOk = true;
    for(let i=0; i<3; i++) {
        for(let j=0; j<3; j++) {
            if(board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) {
                boxOk = false;
                break;
            }
        }
    }
    if (boxOk) sections.push(`box-${boxIdx}`);
    return sections;
};

export const useGameSkills = ({
    board,
    setBoard,
    solvedBoard,
    setHistory,
    moveLog,
    selectedCell,
    activeNumber,
    settings,
    difficulty,
    removeNotesFromPeers,
    checkCompletion,
    onSaveProgress,
    onSectionComplete
}: UseGameSkillsProps) => {

    const [scanUses, setScanUses] = useState(3);
    const [isScanning, setIsScanning] = useState(false);
    const [scanCooldown, setScanCooldown] = useState(false);

    const [revealUses, setRevealUses] = useState(1);
    const [revealingCell, setRevealingCell] = useState<{r: number, c: number} | null>(null);

    const [focusUses, setFocusUses] = useState(3);
    const [focusCell, setFocusCell] = useState<{r: number, c: number} | null>(null);
    const [focusError, setFocusError] = useState<string | null>(null);

    const [animatingCell, setAnimatingCell] = useState<{r: number, c: number, value: number} | null>(null);

    const isBoardComplete = useCallback((currentBoard: Board) => {
        if (solvedBoard.length === 0) return false;
        let filled = 0;
        let correct = 0;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                if (currentBoard[r][c].value !== null) {
                    filled++;
                    if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
                }
            }
        }
        return filled === 81 && correct === 81;
    }, [solvedBoard]);

    const isAutoAvailable = useMemo(() => {
        if (!selectedCell || board.length === 0) return false;
        let r = selectedCell[0];
        let c = selectedCell[1];
        const cell = board[r][c];
        if (cell.value !== null || cell.isRevealed) return false;

        let rowCount = 0;
        for(let i=0; i<9; i++) if (board[r][i].value !== null) rowCount++;
        if (rowCount === 8) return true;

        let colCount = 0;
        for(let i=0; i<9; i++) if (board[i][c].value !== null) colCount++;
        if (colCount === 8) return true;

        let boxCount = 0;
        const startR = Math.floor(r/3)*3;
        const startC = Math.floor(c/3)*3;
        for(let i=0; i<3; i++)
            for(let j=0; j<3; j++)
                if (board[startR+i][startC+j].value !== null) boxCount++;
        if (boxCount === 8) return true;

        return false;
    }, [board, selectedCell]);

    const handleAutoFill = (purchasedSkills: string[]) => {
        if (!purchasedSkills.includes('skill-auto') || !isAutoAvailable || !selectedCell || isScanning || revealingCell) return;
        sounds.playZap(); 
        const [r, c] = selectedCell;

        let valToFill: number | null = null;

        const getMissing = (values: (number | null)[]) => {
            const vals = new Set(values.filter(v => v !== null));
            for (let i = 1; i <= 9; i++) if (!vals.has(i)) return i;
            return null;
        };

        if (board[r].filter(cell => cell.value !== null).length === 8) {
            valToFill = getMissing(board[r].map(c => c.value));
        }
        if (valToFill === null) {
            const colVals = board.map(row => row[c].value);
            if (colVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(colVals);
            }
        }
        if (valToFill === null) {
            const startR = Math.floor(r/3)*3;
            const startC = Math.floor(c/3)*3;
            const boxVals = [];
            for(let i=0; i<3; i++) for(let j=0; j<3; j++) boxVals.push(board[startR+i][startC+j].value);
            if (boxVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(boxVals);
            }
        }

        if (valToFill === null) valToFill = solvedBoard[r][c];

        const val = valToFill as number;
        setAnimatingCell({ r, c, value: 1 });
        setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
        const newBoard = board.map(row => [...row]);

        const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        const isCorrect = val === solvedBoard[r][c];

        newBoard[r][c] = {
            ...newBoard[r][c],
            value: val as any,
            notes: [],
            isError: !isHarderDifficulty ? !isCorrect : false,
            isMarkedWrong: false
        };

        moveLog.current.push({ r, c, v: val, t: Date.now() });

        if (settings.autoEraseNotes) {
             removeNotesFromPeers(newBoard, r, c, val);
        }

        setBoard(newBoard);
        onSaveProgress(newBoard);

        const isFinishingMove = isBoardComplete(newBoard);
        if (!newBoard[r][c].isError && !isFinishingMove) {
            const completedSections = checkSectionCompletion(newBoard, solvedBoard, r, c);
            if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
        }

        const startTime = performance.now();
        const duration = 300; 
        const animate = (time: number) => {
            const elapsed = time - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const currentVal = Math.floor(1 + (val - 1) * progress);
            setAnimatingCell({ r, c, value: currentVal });
            if (progress < 1) requestAnimationFrame(animate);
            else setAnimatingCell(null);
        };
        requestAnimationFrame(animate);
        checkCompletion(newBoard);
    };

    const handleScan = (isPaused: boolean, isCompleted: boolean) => {
        if (scanUses <= 0 || isScanning || scanCooldown || isPaused || isCompleted || revealingCell) return;
        setIsScanning(true);
        setScanCooldown(true);
        sounds.playScan();
        setTimeout(() => {
            const newBoard = board.map(row => row.map(cell => {
                if (!cell.isFixed && cell.value !== null) {
                    const isCorrect = cell.value === solvedBoard[cell.row][cell.col];
                    if (!isCorrect) return { ...cell, isMarkedWrong: true };
                }
                return cell;
            }));
            setBoard(newBoard);
            setIsScanning(false);
            setScanUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, next);
                return next;
            });
            setScanCooldown(false);
        }, 1200); 
    };

    const handleReveal = (isPaused: boolean, isCompleted: boolean) => {
        if (isPaused || isCompleted || revealingCell || isScanning) return;
        if (revealUses <= 0) {
            sounds.playClick();
            return;
        }

        const eligible = [];
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value === null && !cell.isFixed && !cell.isRevealed) {
                    eligible.push({r, c});
                }
            }
        }
        if (eligible.length === 0) return;

        sounds.playReveal(); 
        const target = eligible[Math.floor(Math.random() * eligible.length)];
        setRevealingCell(target);

        setTimeout(() => {
            setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
            const newBoard = board.map(row => [...row]);
            const correctVal = solvedBoard[target.r][target.c];

            newBoard[target.r][target.c] = {
                ...newBoard[target.r][target.c],
                value: correctVal as CellValue,
                notes: [],
                isFixed: false, 
                isRevealed: true, 
                isError: false,
                isMarkedWrong: false
            };

            moveLog.current.push({ r: target.r, c: target.c, v: correctVal, t: Date.now() });

            if (settings.autoEraseNotes) {
                 removeNotesFromPeers(newBoard, target.r, target.c, correctVal);
            }

            setBoard(newBoard);
            setRevealUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, undefined, next);
                return next;
            });

            const isFinishingMove = isBoardComplete(newBoard);
            if (!isFinishingMove) {
                const completedSections = checkSectionCompletion(newBoard, solvedBoard, target.r, target.c);
                if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
            }

            setTimeout(() => {
                setRevealingCell(null);
                checkCompletion(newBoard);
            }, 300); 
        }, 500); 
    };

    const handleFocus = (isPaused: boolean, isCompleted: boolean) => {
        if (focusUses <= 0 || isPaused || isCompleted || focusCell) return;

        // Check for hidden errors (Hard modes)
        const isHard = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;

        // Find if there are any errors on board (value != solved, and not marked as error)
        let hasHiddenErrors = false;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value !== null && cell.value !== solvedBoard[r][c] && !cell.isError && !cell.isMarkedWrong) {
                    hasHiddenErrors = true;
                    break;
                }
            }
            if (hasHiddenErrors) break;
        }

        if (isHard && hasHiddenErrors) {
            setFocusError("You should probably use a Scan...");
            setTimeout(() => setFocusError(null), 3000);
            return;
        }

        // Find logical hint
        const hint = getLogicalHint(board);
        if (hint) {
            sounds.playTap(); // Subtle sound
            setFocusCell(hint);
            setFocusUses(prev => {
                const next = prev - 1;
                onSaveProgress(board, undefined, undefined, next);
                return next;
            });
            // Pulse for 5 seconds
            setTimeout(() => setFocusCell(null), 5000);
        } else {
            // No logic hint found (puzzle might be too hard or filled up)
            // Fallback: Pick a random valid empty cell if board is valid?
            // "Focus" implies Logic. If logic fails, maybe just show "No logical move found" or nothing.
            // But we want to be helpful. If logic fails but board is valid, it's a guess step?
            // Let's just flash error if no hint found.
            setFocusError("No logical moves found.");
            setTimeout(() => setFocusError(null), 2000);
        }
    };

    return {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        focusUses,
        setFocusUses,
        focusCell,
        setFocusCell,
        focusError,
        handleAutoFill,
        handleScan,
        handleReveal,
        handleFocus
    };
};

import React from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    focusCell?: {r: number, c: number} | null; // NEW: Prop for Focus skill
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = ({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    focusCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    const getCellClass = (cell: Cell, r: number, c: number) => {
        let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
        const isConflict = conflicts.has(`${r}-${c}`);
        const isError = cell.isError;
        const isMarkedWrong = cell.isMarkedWrong;
        const isRevealed = cell.isRevealed;
        const isFocused = focusCell?.r === r && focusCell?.c === c;

        const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;

        let isSameValue = false;
        if (settings.digitFirst) {
            if (activeNumber !== null) {
                isSameValue = cell.value === activeNumber;
            } else if (selectedCell && cell.value !== null) {
                 isSameValue = board[selectedCell[0]][selectedCell[1]].value === cell.value;
            }
        } else {
            isSameValue = selectedCell && cell.value !== null && board[selectedCell[0]][selectedCell[1]].value === cell.value;
        }

        const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

        let bgClass = ''; 
        const isThisCellRevealing = revealingCell?.r === r && revealingCell?.c === c;

        if (isThisCellRevealing) {
            bgClass = ''; 
        } else if (isMarkedWrong) {
             bgClass = 'bg-red-200 animate-pulse '; 
        } else if (isError || isConflict) {
             bgClass = 'bg-red-50 ';
        } else if (isSelected) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isSameValue) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isRelated) {
             bgClass = 'bg-stone-200/60 dark:bg-stone-100/50 '; 
        } else if (isRevealed) {
             bgClass = 'bg-amber-100 '; 
        } else {
             bgClass = 'bg-t-board '; 
        }

        classes += bgClass;

        if (isSelected && (isError || isConflict || isMarkedWrong)) {
            classes += "ring-2 ring-inset ring-red-400 z-10 ";
        }

        if (isThisCellRevealing) {
            classes += "animate-reveal-premium z-50 relative ";
        }

        if (isFocused) {
            // Apply pulsating ring for Focus skill
            classes += "ring-4 ring-inset ring-teal-400/80 animate-pulse z-40 ";
        }

        if (cell.isFixed) {
            classes += "font-semibold text-stone-800 ";
        } else if (isRevealed) {
            classes += "font-semibold text-stone-800 ";
        } else {
            if (isError || isConflict || isMarkedWrong) {
                classes += "font-medium text-red-500 ";
            } else {
                classes += "font-medium ";
            }
        }
        return classes;
    };

    const getSectionOverlayStyle = (sectionId: string) => {
        if (sectionId === 'full-board') {
            return {
                position: 'absolute' as const,
                pointerEvents: 'none' as const,
                zIndex: 60,
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                borderWidth: '8px' // Make completion border more prominent
            };
        }

        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 60 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-[10px]">
            <div className="bg-t-board border-2 border-stone-800 rounded-lg overflow-hidden relative flex-none shadow-lg" style={{ width: squareSize, height: squareSize, maxWidth: '500px', maxHeight: '500px' }}>

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;

                    return (
                        <div 
                            key={`${rIndex}-${cIndex}`} 
                            className={getCellClass(cell, rIndex, cIndex)} 
                            onClick={(e) => {
                                e.stopPropagation();
                                onCellClick(e, rIndex, cIndex);
                            }} 
                            style={{ fontSize: mainFontSize }}
                        >
                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] ${!cell.isFixed && !cell.isError && !cell.isMarkedWrong && !cell.isRevealed ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none">
                                {[1,2,3,4,5,6,7,8,9].map(n => (
                                    <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                        <span className={cell.notes.includes(n) ? 'text-stone-500' : 'invisible'}>{n}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>

            {/* Section/Board Completion Borders */}
            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className={`absolute box-border border-emerald-300 shadow-[0_0_30px_rgba(16,185,129,0.9)] animate-section-complete ${sectionId === 'full-board' ? 'rounded-lg border-4' : 'rounded-sm border-2'}`}
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
};

import React from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { SkillTooltip } from '../ui/SkillTooltip';

interface GameControlsProps {
    canUndo: boolean;
    canErase: boolean;
    isPencilMode: boolean;
    onUndo: (e: React.MouseEvent) => void;
    onErase: (e: React.MouseEvent) => void;
    onTogglePencil: (e: React.MouseEvent) => void;
    purchasedSkills: string[];
    // Skill specific props
    isAutoAvailable: boolean;
    scanUses: number;
    isScanning: boolean;
    scanCooldown: boolean;
    revealUses: number;
    revealingCell: {r: number, c: number} | null;
    focusUses: number;
    focusError: string | null;
    onAutoFill: (e: React.MouseEvent) => void;
    onScan: (e: React.MouseEvent) => void;
    onReveal: (e: React.MouseEvent) => void;
    onFocus: (e: React.MouseEvent) => void;
}

export const GameControls: React.FC<GameControlsProps> = ({
    canUndo,
    canErase,
    isPencilMode,
    onUndo,
    onErase,
    onTogglePencil,
    purchasedSkills,
    isAutoAvailable,
    scanUses,
    isScanning,
    scanCooldown,
    revealUses,
    revealingCell,
    focusUses,
    focusError,
    onAutoFill,
    onScan,
    onReveal,
    onFocus
}) => {
    // Helper for common enabled/disabled styles
    const getBaseButtonStyle = (isEnabled: boolean) => 
        isEnabled 
            ? 'text-stone-900 dark:text-stone-100 cursor-pointer hover:brightness-95 active:scale-95' 
            : 'text-stone-300 dark:text-stone-600 cursor-not-allowed';

    const getBaseContainerStyle = (isEnabled: boolean) => 
        isEnabled
            ? 'bg-white dark:bg-stone-800 border-stone-300 dark:border-stone-600'
            : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700';

    return (
        <div className="flex justify-between w-full relative">
            {/* Reveal Skill Button */}
            {purchasedSkills.includes('skill-reveal') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onReveal(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(revealUses > 0 && !revealingCell)}`}
                        disabled={!!revealingCell}
                    >
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(revealUses > 0)}`}>
                        <Icons.Reveal className={`w-5 h-5 ${revealUses > 0 ? 'text-purple-600 dark:text-purple-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold border-2 border-t-surface leading-none ${revealUses > 0 ? 'bg-blue-600 text-white' : 'bg-stone-300 text-white dark:bg-stone-600'}`}>
                                {revealUses > 0 ? revealUses : '+'}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Reveal</span>
                </button>
            )}

            {/* Scan Skill Button */}
            {purchasedSkills.includes('skill-scan') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onScan(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}
                        disabled={scanUses <= 0 || scanCooldown || isScanning}
                    >
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}>
                        <Icons.Scan className={`w-5 h-5 ${scanUses > 0 && !scanCooldown && !isScanning ? 'text-red-600 dark:text-red-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        {scanUses > 0 && (
                            <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold border-2 border-t-surface leading-none ${scanUses > 0 ? 'bg-blue-600 text-white' : 'hidden'}`}>
                                {scanUses}
                            </div>
                        )}
                    </div>
                    <span className="text-sm font-medium">Scan</span>
                </button>
            )}

            {/* Focus Skill Button */}
            {purchasedSkills.includes('skill-focus') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onFocus(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(focusUses > 0)}`}
                        disabled={focusUses <= 0}
                    >
                    {/* Error Tooltip */}
                    {focusError && (
                         <SkillTooltip text={focusError} isClosing={false} />
                    )}

                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(focusUses > 0)} ${focusError ? 'animate-shake border-red-400 bg-red-50' : ''}`}>
                        <Icons.Focus className={`w-5 h-5 ${focusUses > 0 ? 'text-teal-500 dark:text-teal-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        {focusUses > 0 && (
                            <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold border-2 border-t-surface leading-none ${focusUses > 0 ? 'bg-blue-600 text-white' : 'hidden'}`}>
                                {focusUses}
                            </div>
                        )}
                    </div>
                    <span className="text-sm font-medium">Focus</span>
                </button>
            )}

            {/* Auto Skill Button */}
            {purchasedSkills.includes('skill-auto') && (
                <button 
                    onClick={(e) => { e.stopPropagation(); onAutoFill(e); }} 
                    className={`flex flex-col items-center gap-1 transition relative active:scale-95 ${isAutoAvailable ? 'cursor-pointer text-amber-700 dark:text-amber-400' : 'cursor-not-allowed text-stone-300 dark:text-stone-600'}`}
                    disabled={!isAutoAvailable}
                >
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 ${
                        isAutoAvailable 
                        ? 'bg-amber-100 border-amber-300 ring-1 ring-amber-200 dark:bg-amber-900/30 dark:border-amber-700 dark:ring-amber-900/50' 
                        : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
                    </div>
                    <span className="text-sm font-medium">Auto</span>
                </button>
            )}

            {/* UNDO BUTTON */}
            <button 
                onClick={onUndo} 
                disabled={!canUndo}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canUndo)}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${getBaseContainerStyle(canUndo)}`}>
                    <Icons.Undo className={`w-5 h-5 ${canUndo ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Undo</span>
            </button>

            {/* PENCIL BUTTON */}
            <button 
                onClick={onTogglePencil} 
                className={`flex flex-col items-center gap-1 active:scale-95 transition cursor-pointer hover:brightness-95 ${isPencilMode ? 'text-blue-700 dark:text-blue-300' : 'text-stone-900 dark:text-stone-100'}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${
                    isPencilMode 
                    ? 'bg-blue-100 border-blue-400 dark:bg-blue-900/40 dark:border-blue-700' 
                    : 'bg-white dark:bg-stone-800 border-stone-300 dark:border-stone-600'
                }`}>
                    <Icons.Pencil className={`w-5 h-5 ${isPencilMode ? 'text-blue-600 dark:text-blue-400' : 'text-stone-700 dark:text-stone-300'}`} />
                </div>
                <span className="text-sm font-medium">Pencil</span>
            </button>

            {/* ERASE BUTTON */}
            <button 
                onClick={onErase} 
                disabled={!canErase}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canErase)}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${getBaseContainerStyle(canErase)}`}>
                    <Icons.Erase className={`w-5 h-5 ${canErase ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Erase</span>
            </button>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number, focusUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses,
          focusUses: focusUsesVal !== undefined ? focusUsesVal : focusUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses,
          focusUses
      });

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation (might not have gesture context here if async, but handled gracefully)
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      focusUses,
      setFocusUses,
      focusCell,
      focusError,
      handleAutoFill,
      handleScan,
      handleReveal,
      handleFocus
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r, f) => saveProgress(b, s, r, f),
      onSectionComplete: handleSectionComplete
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
      if (savedProgress.focusUses !== undefined) setFocusUses(savedProgress.focusUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
      setFocusUses(3);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves (e.g. reload), reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            // Row-by-row fill
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `Oku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Oku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setFocusUses(3);
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleDebugWin = () => {
      const newBoard: Board = board.map((row, r) => 
          row.map((cell, c) => ({
              ...cell,
              value: solvedBoard[r][c] as any,
              notes: [],
              isError: false
          }))
      );
      setBoard(newBoard);
      handleGameComplete(newBoard);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  // Determine if erase is possible for the selected cell (value or notes)
  const canErase = !!selectedCell && (() => {
      const [r, c] = selectedCell;
      const cell = board[r][c];
      return !cell.isFixed && (cell.value !== null || cell.notes.length > 0);
  })();

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-[70px] pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-t-secondary uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <SudokuGrid 
             board={board}
             selectedCell={selectedCell}
             activeNumber={activeNumber}
             conflicts={conflicts}
             revealingCell={revealingCell}
             animatingCell={animatingCell}
             focusCell={focusCell}
             isScanning={isScanning}
             animatingSections={animatingSections}
             settings={settings}
             numberColor={numberColor}
             onCellClick={(e, r, c) => handleCellClick(r, c, isPaused, isCompleted)}
         />

         <div className="w-full max-w-md px-6 mt-4 flex flex-col gap-6" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={canErase}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 focusUses={focusUses}
                 focusError={focusError}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
                 onFocus={() => handleFocus(isPaused, isCompleted)}
             />

             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={(e, n) => handleNumberInput(n, isPaused, isCompleted)}
             />
         </div>

         <div className={`mt-5 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-sm font-light text-stone-400 dark:text-stone-500 tracking-wide">TAP HERE TO DESELECT</span>
         </div>

         <button 
             onClick={(e) => { e.stopPropagation(); handleDebugWin(); }}
             className="mb-6 px-6 py-3 bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-red-200 dark:hover:bg-red-900/50 transition-colors"
         >
             Auto Solve (Debug)
         </button>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import { Difficulty, Board, Cell, CellValue } from '../types';
import { IMPOSSIBLE_SEEDS } from './constants';

// Improved seeded random number generator (Mulberry32)
// Good distribution, fast, 32-bit state
class SeededRandom {
    seed: number;
    constructor(seed: number) {
        this.seed = seed;
    }

    // Returns a number between 0 and 1
    next(): number {
        var t = this.seed += 0x6D2B79F5;
        t = Math.imul(t ^ t >>> 15, t | 1);
        t ^= t + Math.imul(t ^ t >>> 7, t | 61);
        return ((t ^ t >>> 14) >>> 0) / 4294967296;
    }
}

// Helper to check if placing num at board[row][col] is valid (Standard Rules)
export function isValid(board: number[][], row: number, col: number, num: number): boolean {
  // Check Row
  for (let c = 0; c < 9; c++) {
    if (board[row][c] === num) return false;
  }

  // Check Column
  for (let r = 0; r < 9; r++) {
    if (board[r][col] === num) return false;
  }

  // Check 3x3 Box
  const startRow = Math.floor(row / 3) * 3;
  const startCol = Math.floor(col / 3) * 3;
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      if (board[startRow + i][startCol + j] === num) {
        return false;
      }
    }
  }
  return true;
}

// Counts solutions to ensure uniqueness.
// Optimized using MRV (Minimum Remaining Values) heuristic
function countSolutions(board: number[][]): number {
    let row = -1;
    let col = -1;
    let minOptions = 10;

    // Find cell with fewest options
    outer: for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            if (board[r][c] === 0) {
                let options = 0;
                for (let k = 1; k <= 9; k++) {
                     if (isValid(board, r, c, k)) options++;
                }

                if (options === 0) return 0; // Impossible state (no candidates for an empty cell)

                if (options < minOptions) {
                    minOptions = options;
                    row = r;
                    col = c;
                }
                // Optimization: If a cell has only 1 option, we must pick it. No need to search further.
                if (minOptions === 1) break outer;
            }
        }
    }

    // If no empty cells found, we found a valid solution
    if (row === -1) {
        return 1;
    }

    let count = 0;
    for (let num = 1; num <= 9; num++) {
        if (isValid(board, row, col, num)) {
            board[row][col] = num;
            count += countSolutions(board);
            board[row][col] = 0; // Backtrack

            if (count > 1) return count; // Early exit if not unique
        }
    }

    return count;
}

// Generates a full valid 9x9 Sudoku board
function generateFullBoard(rng: SeededRandom): number[][] {
  const board = Array.from({ length: 9 }, () => Array(9).fill(0));

  function fill(idx: number): boolean {
      if (idx === 81) return true;

      const row = Math.floor(idx / 9);
      const col = idx % 9;

      // Randomize 1-9 check order
      const nums = [1, 2, 3, 4, 5, 6, 7, 8, 9]
          .map(value => ({ value, sort: rng.next() }))
          .sort((a, b) => a.sort - b.sort)
          .map(({ value }) => value);

      for (const num of nums) {
          if (isValid(board, row, col, num)) {
              board[row][col] = num;
              if (fill(idx + 1)) return true;
              board[row][col] = 0;
          }
      }
      return false;
  }

  fill(0);
  return board;
}

// --- LOGICAL SOLVER ---
// This class simulates a human player to verify difficulty.
// It maintains a list of candidates for every cell and reduces them using logic.

class LogicalSolver {
    candidates: number[][][]; // [row][col] -> number[]
    solvedCount: number = 0;

    constructor(initialBoard: number[][]) {
        // Initialize candidates: 1-9 for empty cells, [val] for filled cells
        this.candidates = [];
        for(let r=0; r<9; r++) {
            const rowCands = [];
            for(let c=0; c<9; c++) {
                if (initialBoard[r][c] !== 0) {
                    rowCands.push([initialBoard[r][c]]);
                    this.solvedCount++;
                } else {
                    rowCands.push([1,2,3,4,5,6,7,8,9]);
                }
            }
            this.candidates.push(rowCands);
        }

        // Initial propagation: Remove filled numbers from peers
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                if (initialBoard[r][c] !== 0) {
                    this.eliminatePeers(r, c, initialBoard[r][c]);
                }
            }
        }
    }

    // Removes 'val' from all peers (row, col, box) of (r,c)
    // Returns true if any candidate was removed
    private eliminatePeers(r: number, c: number, val: number): boolean {
        let changed = false;

        // Row & Col
        for(let i=0; i<9; i++) {
            if (i !== c && this.removeCandidate(r, i, val)) changed = true;
            if (i !== r && this.removeCandidate(i, c, val)) changed = true;
        }

        // Box
        const startR = Math.floor(r/3)*3;
        const startC = Math.floor(c/3)*3;
        for(let i=0; i<3; i++) {
            for(let j=0; j<3; j++) {
                const rr = startR + i;
                const cc = startC + j;
                if ((rr !== r || cc !== c) && this.removeCandidate(rr, cc, val)) changed = true;
            }
        }
        return changed;
    }

    // Removes 'val' from candidates of (r,c)
    // If a cell reduces to 1 candidate (Naked Single), it automatically propagates (cascading effect)
    private removeCandidate(r: number, c: number, val: number): boolean {
        const cands = this.candidates[r][c];
        if (cands.length <= 1) return false; // Already solved or empty

        const idx = cands.indexOf(val);
        if (idx !== -1) {
            cands.splice(idx, 1);
            if (cands.length === 1) {
                this.solvedCount++;
                // Cascade propagation (Naked Single logic)
                this.eliminatePeers(r, c, cands[0]);
            }
            return true;
        }
        return false;
    }

    // Tier 1 Logic: Hidden Singles
    // Checks if a number exists in only one spot within a unit (Row/Col/Box)
    private applyHiddenSingles(): boolean {
        let changed = false;
        // 0=Row, 1=Col, 2=Box
        for (let unitType = 0; unitType < 3; unitType++) {
            for (let unitIdx = 0; unitIdx < 9; unitIdx++) {
                const counts: {[key: number]: {count: number, r: number, c: number}} = {};

                // Scan unit
                for (let i = 0; i < 9; i++) {
                    let r, c;
                    if (unitType === 0) { r = unitIdx; c = i; }
                    else if (unitType === 1) { r = i; c = unitIdx; }
                    else { r = Math.floor(unitIdx/3)*3 + Math.floor(i/3); c = (unitIdx%3)*3 + (i%3); }

                    // Only check unsolved cells
                    if (this.candidates[r][c].length > 1) {
                        for (const val of this.candidates[r][c]) {
                            if (!counts[val]) counts[val] = { count: 0, r, c };
                            counts[val].count++;
                            // Optimization: if count > 1 we can stop tracking position, but logic is simpler this way
                        }
                    }
                }

                // Apply logic
                for (let n = 1; n <= 9; n++) {
                    if (counts[n] && counts[n].count === 1) {
                        // Found Hidden Single
                        const { r, c } = counts[n];
                        // Remove all other candidates from this cell
                        const cands = this.candidates[r][c];
                        const others = cands.filter(v => v !== n);
                        for (const other of others) {
                            this.removeCandidate(r, c, other);
                        }
                        changed = true;
                    }
                }
            }
        }
        return changed;
    }

    // Tier 2 Logic: Intersection Removal (Locked Candidates - Pointing & Claiming)
    private applyLockedCandidates(): boolean {
        let changed = false;

        // Check Boxes
        for (let b = 0; b < 9; b++) {
            const startR = Math.floor(b/3)*3;
            const startC = (b%3)*3;

            for (let n = 1; n <= 9; n++) {
                const rowsWithN = new Set<number>();
                const colsWithN = new Set<number>();

                // Find all positions of N in this box
                for(let i=0; i<3; i++) {
                    for(let j=0; j<3; j++) {
                        if (this.candidates[startR+i][startC+j].includes(n)) {
                            rowsWithN.add(startR+i);
                            colsWithN.add(startC+j);
                        }
                    }
                }

                // Pointing Pair (Box -> Row)
                if (rowsWithN.size === 1) {
                    const r = Array.from(rowsWithN)[0];
                    // Remove N from rest of the row outside this box
                    for (let c = 0; c < 9; c++) {
                        if (c < startC || c >= startC + 3) {
                            if (this.removeCandidate(r, c, n)) changed = true;
                        }
                    }
                }

                // Pointing Pair (Box -> Col)
                if (colsWithN.size === 1) {
                    const c = Array.from(colsWithN)[0];
                    // Remove N from rest of the col outside this box
                    for (let r = 0; r < 9; r++) {
                        if (r < startR || r >= startR + 3) {
                            if (this.removeCandidate(r, c, n)) changed = true;
                        }
                    }
                }
            }
        }
        return changed;
    }

    // Tier 3 Logic: Naked Pairs
    private applyNakedPairs(): boolean {
        let changed = false;

        // Helper to check units
        const checkUnit = (coords: {r: number, c:number}[]) => {
            // Find cells with exactly 2 candidates
            const pairs: { [key: string]: {r:number, c:number}[] } = {};

            coords.forEach(({r,c}) => {
                if (this.candidates[r][c].length === 2) {
                    const key = this.candidates[r][c].join(',');
                    if (!pairs[key]) pairs[key] = [];
                    pairs[key].push({r,c});
                }
            });

            // If we have exactly 2 cells with the same 2 candidates, it's a Naked Pair
            for (const key in pairs) {
                if (pairs[key].length === 2) {
                    const [v1, v2] = key.split(',').map(Number);
                    const pairCells = pairs[key];

                    // Remove v1, v2 from all OTHER cells in unit
                    coords.forEach(({r,c}) => {
                        // Skip the pair cells themselves
                        if (pairCells.some(p => p.r === r && p.c === c)) return;

                        if (this.removeCandidate(r, c, v1)) changed = true;
                        if (this.removeCandidate(r, c, v2)) changed = true;
                    });
                }
            }
        };

        // Check Rows
        for (let r=0; r<9; r++) {
            const coords = [];
            for(let c=0; c<9; c++) coords.push({r,c});
            checkUnit(coords);
        }

        // Check Cols
        for (let c=0; c<9; c++) {
            const coords = [];
            for(let r=0; r<9; r++) coords.push({r,c});
            checkUnit(coords);
        }

        // Check Boxes
        for (let b=0; b<9; b++) {
            const startR = Math.floor(b/3)*3;
            const startC = (b%3)*3;
            const coords = [];
            for(let i=0; i<3; i++) for(let j=0; j<3; j++) coords.push({r: startR+i, c: startC+j});
            checkUnit(coords);
        }

        return changed;
    }

    // Attempt to solve the puzzle using logic up to maxTier
    // Tier 1: Singles (Naked & Hidden)
    // Tier 2: + Intersections (Locked Candidates)
    // Tier 3: + Subsets (Naked Pairs)
    public solve(maxTier: number): boolean {
        let changed = true;
        while(changed && this.solvedCount < 81) {
            changed = false;

            // Note: removeCandidate automatically propagates Naked Singles via eliminatePeers.
            // So we don't need an explicit "applyNakedSingles".

            // Check Hidden Singles (Tier 1)
            if (this.applyHiddenSingles()) {
                changed = true;
                continue; // Restart loop to ripple new singles
            }

            if (maxTier >= 2) {
                if (this.applyLockedCandidates()) {
                    changed = true;
                    continue;
                }
            }

            if (maxTier >= 3) {
                if (this.applyNakedPairs()) {
                    changed = true;
                    continue;
                }
            }
        }
        return this.solvedCount === 81;
    }

    // NEW: Find the first available logical move
    public findHint(): {r: number, c: number} | null {
        // 1. Check for Naked Singles (Cells with 1 candidate)
        for (let r=0; r<9; r++) {
            for (let c=0; c<9; c++) {
                if (this.candidates[r][c].length === 1) {
                    // Check if the original board had this value (it's already solved)
                    // But we constructed LogicalSolver with filled values from board.
                    // If candidates len is 1, it means we found a deduction (or it's an existing filled cell)
                    // Wait, constructor sets candidates for filled cells to [val].
                    // So we need to filter out cells that were already non-zero in input board.
                    // However, we don't have reference to initial board here easily unless passed.
                    // But we can check if it was part of the problem.
                    // Actually, finding a hint usually implies finding something that is NOT filled yet.
                    // But the LogicalSolver fills in deductions into candidates.
                    // So we need to cross reference with the board state passed in.
                }
            }
        }
        return null;
    }
}

// Helper function to expose hint finding
export function getLogicalHint(board: Board): {r: number, c: number} | null {
    // Convert Board to number[][]
    const simpleBoard = board.map(row => row.map(cell => cell.value || 0));

    // Instantiate solver (automatically finds Naked Singles via initial constraint propagation)
    const solver = new LogicalSolver(simpleBoard);

    const nakedSingles: {r: number, c: number}[] = [];

    // 1. COLLECT ALL Naked Singles (Cells with 1 candidate)
    for (let r=0; r<9; r++) {
        for (let c=0; c<9; c++) {
            if (simpleBoard[r][c] === 0) {
                if (solver.candidates[r][c].length === 1) {
                    nakedSingles.push({ r, c });
                }
            }
        }
    }

    // If we have any Naked Singles, pick one randomly.
    // This breaks the "top-left to bottom-right" pattern and provides variety.
    // Naked singles are the "purest" logical hint.
    if (nakedSingles.length > 0) {
        const randomIndex = Math.floor(Math.random() * nakedSingles.length);
        return nakedSingles[randomIndex];
    }

    // 2. COLLECT ALL Hidden Singles if no Naked Singles
    // Iterate units (Row, Col, Box)
    const hiddenSingles: {r: number, c: number}[] = [];

    for (let unitType = 0; unitType < 3; unitType++) {
        for (let unitIdx = 0; unitIdx < 9; unitIdx++) {
            const counts: {[key: number]: {count: number, r: number, c: number}} = {};
            // Scan unit
            for (let i = 0; i < 9; i++) {
                let r, c;
                if (unitType === 0) { r = unitIdx; c = i; }
                else if (unitType === 1) { r = i; c = unitIdx; }
                else { r = Math.floor(unitIdx/3)*3 + Math.floor(i/3); c = (unitIdx%3)*3 + (i%3); }

                // Only count candidates in empty cells
                if (simpleBoard[r][c] === 0) {
                     const cands = solver.candidates[r][c];
                     for (const val of cands) {
                        if (!counts[val]) counts[val] = { count: 0, r, c };
                        counts[val].count++;
                     }
                }
            }

            // Check counts for uniqueness
            for (let n = 1; n <= 9; n++) {
                if (counts[n] && counts[n].count === 1) {
                    const { r, c } = counts[n];
                    // Add if unique (avoid duplicates if cell is hidden single in multiple units)
                    if (!hiddenSingles.some(h => h.r === r && h.c === c)) {
                        hiddenSingles.push({ r, c });
                    }
                }
            }
        }
    }

    // Pick random Hidden Single
    if (hiddenSingles.length > 0) {
        const randomIndex = Math.floor(Math.random() * hiddenSingles.length);
        return hiddenSingles[randomIndex];
    }

    return null;
}

function getDifficultySeed(diff: Difficulty): number {
    switch(diff) {
        case Difficulty.SuperEasy: return 1000;
        case Difficulty.Easy: return 2000;
        case Difficulty.Normal: return 3000;
        case Difficulty.Hard: return 4000;
        case Difficulty.Intense: return 5000;
        case Difficulty.Impossible: return 6000;
        default: return 0;
    }
}

// Logic Configuration for each difficulty
const DIFFICULTY_CONFIG = {
    [Difficulty.SuperEasy]: { tier: 1, minClues: 48 }, // Relaxing, scanning only
    [Difficulty.Easy]:      { tier: 1, minClues: 40 }, // Deeper scanning
    [Difficulty.Normal]:    { tier: 2, minClues: 36 }, // Requires Pointing/Claiming
    [Difficulty.Hard]:      { tier: 3, minClues: 32 }, // Requires Pairs
    [Difficulty.Intense]:   { tier: 3, minClues: 26 }, // Aggressive digging
    [Difficulty.Impossible]:{ tier: 4, minClues: 0 }   // No logic check (Unrestricted)
};

// Helper function to generate a single attempt
function generateAttempt(difficulty: Difficulty, seed: number): { initial: Board, solved: number[][], clues: number } {
    const rng = new SeededRandom(seed);

    // 1. Generate a solved board
    const solvedRaw = generateFullBoard(rng);

    // 2. Clone it to create the puzzle
    const puzzleRaw = solvedRaw.map(row => [...row]);

    const config = DIFFICULTY_CONFIG[difficulty];
    const targetClues = config.minClues;

    // 3. Create shuffled list of positions
    const positions = Array.from({length: 81}, (_, i) => i);
    // Fisher-Yates shuffle
    for (let i = positions.length - 1; i > 0; i--) {
        const j = Math.floor(rng.next() * (i + 1));
        [positions[i], positions[j]] = [positions[j], positions[i]];
    }

    // 4. Dig Holes
    let currentClues = 81;

    for (const pos of positions) {
        // Stop if we hit target clue count (prevents SuperEasy from becoming too sparse)
        if (targetClues > 0 && currentClues <= targetClues) break;

        const r = Math.floor(pos / 9);
        const c = pos % 9;
        const backup = puzzleRaw[r][c];

        // Tentatively remove
        puzzleRaw[r][c] = 0;

        // CHECK 1: Uniqueness (Absolute Rule)
        // We assume countSolutions is fast enough for backtracker check
        const boardCopy = puzzleRaw.map(row => [...row]);
        const solutions = countSolutions(boardCopy);

        if (solutions !== 1) {
            puzzleRaw[r][c] = backup; // Put it back
            continue;
        }

        // CHECK 2: Logic Grading (Difficulty Rule)
        // For Impossible (Tier 4), we skip logic check and just dig deep
        if (config.tier < 4) {
            const solver = new LogicalSolver(puzzleRaw);
            const isSolvable = solver.solve(config.tier);

            if (!isSolvable) {
                puzzleRaw[r][c] = backup; // Put it back (Needs this clue for this difficulty)
                continue;
            }
        }

        // Removal Accepted
        currentClues--;
    }

    // 5. Convert to rich Cell objects
    const initial: Board = puzzleRaw.map((row, rIndex) => 
        row.map((val, cIndex) => ({
            row: rIndex,
            col: cIndex,
            value: val === 0 ? null : (val as CellValue),
            isFixed: val !== 0,
            notes: [],
            isError: false
        }))
    );

    return { initial, solved: solvedRaw, clues: currentClues };
}

export function generateLevel(difficulty: Difficulty, levelId: number): { initial: Board, solved: number[][] } {

    // GOLDEN SEEDS STRATEGY (Impossible Difficulty)
    // Instead of generating at runtime (slow), we pick from a list of pre-mined seeds.
    if (difficulty === Difficulty.Impossible) {
        // Deterministically pick a seed from the pool based on Level ID
        const seedIndex = (levelId - 1) % IMPOSSIBLE_SEEDS.length;
        const goldenSeed = IMPOSSIBLE_SEEDS[seedIndex];

        // This generates ONE board instantly using the golden seed.
        // We assume the seed guarantees the clue count.
        const attempt = generateAttempt(difficulty, goldenSeed);
        return { initial: attempt.initial, solved: attempt.solved };
    }

    // Standard generation for other difficulties
    const seedBase = getDifficultySeed(difficulty);
    const baseSeed = levelId + seedBase + 9999;
    const attempt = generateAttempt(difficulty, baseSeed);
    return { initial: attempt.initial, solved: attempt.solved };
}

// --- MINING TOOL ---
// Run this in the browser console: window.mineSudokuSeeds(1, 300)
// It will look for seeds that produce puzzles with <= 22 clues AND match difficulty.
(window as any).mineSudokuSeeds = (startSeed: number = 1, count: number = 50) => {
    console.log(`%c ⛏️ SUDOKU MINER STARTED (Target: ${count} seeds, <= 22 Clues, Hard Logic) `, 'background: #222; color: #bada55; padding: 5px;');

    const results: number[] = [];
    let seed = startSeed;
    let attempts = 0;
    const maxAttempts = 1000000; // Allow it to run longer

    const startTime = performance.now();

    while(results.length < count && attempts < maxAttempts) {
        attempts++;
        // Use Impossible to allow digging to 0, but we will check logic ourselves
        const attempt = generateAttempt(Difficulty.Impossible, seed);

        if (attempt.clues <= 22) {
             // EXTRA CHECK: Is it actually hard? 
             // Convert back to simple board for solver
             const simpleBoard = attempt.initial.map(r => r.map(c => c.value || 0));
             const solver = new LogicalSolver(simpleBoard);
             // If Tier 3 (Naked Pairs) CANNOT solve it, it's a true "Impossible" candidate
             const isEasy = solver.solve(3);

             if (!isEasy) {
                results.push(seed);
                console.log(`%c [${results.length}/${count}] Seed: ${seed} | Clues: ${attempt.clues} (Impossible Verified) `, 'color: #10b981');
             }
        }

        if (attempts % 1000 === 0) console.log(`Searched ${attempts} seeds... found ${results.length}`);
        seed++;
    }

    const endTime = performance.now();
    console.log(`%c MINING COMPLETE in ${((endTime - startTime)/1000).toFixed(2)}s `, 'background: #222; color: #bada55; padding: 5px;');
    console.log(`Found ${results.length} seeds.`);
    console.log(`%c COPY THE ARRAY BELOW INTO constants.ts (IMPOSSIBLE_SEEDS):`, 'font-weight: bold;');
    console.log(JSON.stringify(results));
}

import React, { useState, useMemo, SetStateAction, Dispatch, useCallback, useRef, useEffect } from 'react';
import { Board, Difficulty, CellValue, AppSettings } from '../types';
import { sounds } from '../utils/sound';
import { getLogicalHint } from '../utils/sudoku';

interface UseGameSkillsProps {
    board: Board;
    setBoard: Dispatch<SetStateAction<Board>>;
    solvedBoard: number[][];
    setHistory: Dispatch<SetStateAction<Board[]>>;
    moveLog: React.MutableRefObject<{r: number, c: number, v: number, t: number}[]>;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    settings: AppSettings;
    difficulty: Difficulty;
    removeNotesFromPeers: (board: Board, r: number, c: number, val: number) => void;
    checkCompletion: (board: Board) => void;
    onSaveProgress: (board: Board, scanUses?: number, revealUses?: number, focusUses?: number) => void;
    onSectionComplete?: (sections: string[]) => void;
}

const checkSectionCompletion = (board: Board, solvedBoard: number[][], r: number, c: number) => {
    const sections: string[] = [];
    // Row
    if (board[r].every((cell, idx) => cell.value === solvedBoard[r][idx])) sections.push(`row-${r}`);
    // Col
    if (board.every((row, idx) => row[c].value === solvedBoard[idx][c])) sections.push(`col-${c}`);
    // Box
    const startR = Math.floor(r/3)*3;
    const startC = Math.floor(c/3)*3;
    const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
    let boxOk = true;
    for(let i=0; i<3; i++) {
        for(let j=0; j<3; j++) {
            if(board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) {
                boxOk = false;
                break;
            }
        }
    }
    if (boxOk) sections.push(`box-${boxIdx}`);
    return sections;
};

export const useGameSkills = ({
    board,
    setBoard,
    solvedBoard,
    setHistory,
    moveLog,
    selectedCell,
    activeNumber,
    settings,
    difficulty,
    removeNotesFromPeers,
    checkCompletion,
    onSaveProgress,
    onSectionComplete
}: UseGameSkillsProps) => {

    const [scanUses, setScanUses] = useState(3);
    const [isScanning, setIsScanning] = useState(false);
    const [scanCooldown, setScanCooldown] = useState(false);

    const [revealUses, setRevealUses] = useState(1);
    const [revealingCell, setRevealingCell] = useState<{r: number, c: number} | null>(null);

    const [focusUses, setFocusUses] = useState(3);
    const [focusCell, setFocusCell] = useState<{r: number, c: number, isFading: boolean} | null>(null);
    const [focusError, setFocusError] = useState<string | null>(null);

    // Internal cooldown state for Focus (invisible to user UI)
    const [focusCooldown, setFocusCooldown] = useState(false);

    const focusTimeoutRef = useRef<any>(null);
    const fadeTimeoutRef = useRef<any>(null);

    const [animatingCell, setAnimatingCell] = useState<{r: number, c: number, value: number} | null>(null);

    // Cleanup timers on unmount
    useEffect(() => {
        return () => {
            if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);
            if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);
        };
    }, []);

    const isBoardComplete = useCallback((currentBoard: Board) => {
        if (solvedBoard.length === 0) return false;
        let filled = 0;
        let correct = 0;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                if (currentBoard[r][c].value !== null) {
                    filled++;
                    if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
                }
            }
        }
        return filled === 81 && correct === 81;
    }, [solvedBoard]);

    const isAutoAvailable = useMemo(() => {
        if (!selectedCell || board.length === 0) return false;
        let r = selectedCell[0];
        let c = selectedCell[1];
        const cell = board[r][c];
        if (cell.value !== null || cell.isRevealed) return false;

        let rowCount = 0;
        for(let i=0; i<9; i++) if (board[r][i].value !== null) rowCount++;
        if (rowCount === 8) return true;

        let colCount = 0;
        for(let i=0; i<9; i++) if (board[i][c].value !== null) colCount++;
        if (colCount === 8) return true;

        let boxCount = 0;
        const startR = Math.floor(r/3)*3;
        const startC = Math.floor(c/3)*3;
        for(let i=0; i<3; i++)
            for(let j=0; j<3; j++)
                if (board[startR+i][startC+j].value !== null) boxCount++;
        if (boxCount === 8) return true;

        return false;
    }, [board, selectedCell]);

    const handleAutoFill = (purchasedSkills: string[]) => {
        if (!purchasedSkills.includes('skill-auto') || !isAutoAvailable || !selectedCell || isScanning || revealingCell) return;
        sounds.playZap(); 
        const [r, c] = selectedCell;

        let valToFill: number | null = null;

        const getMissing = (values: (number | null)[]) => {
            const vals = new Set(values.filter(v => v !== null));
            for (let i = 1; i <= 9; i++) if (!vals.has(i)) return i;
            return null;
        };

        if (board[r].filter(cell => cell.value !== null).length === 8) {
            valToFill = getMissing(board[r].map(c => c.value));
        }
        if (valToFill === null) {
            const colVals = board.map(row => row[c].value);
            if (colVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(colVals);
            }
        }
        if (valToFill === null) {
            const startR = Math.floor(r/3)*3;
            const startC = Math.floor(c/3)*3;
            const boxVals = [];
            for(let i=0; i<3; i++) for(let j=0; j<3; j++) boxVals.push(board[startR+i][startC+j].value);
            if (boxVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(boxVals);
            }
        }

        if (valToFill === null) valToFill = solvedBoard[r][c];

        const val = valToFill as number;
        setAnimatingCell({ r, c, value: 1 });
        setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
        const newBoard = board.map(row => [...row]);

        const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        const isCorrect = val === solvedBoard[r][c];

        newBoard[r][c] = {
            ...newBoard[r][c],
            value: val as any,
            notes: [],
            isError: !isHarderDifficulty ? !isCorrect : false,
            isMarkedWrong: false
        };

        moveLog.current.push({ r, c, v: val, t: Date.now() });

        if (settings.autoEraseNotes) {
             removeNotesFromPeers(newBoard, r, c, val);
        }

        setBoard(newBoard);
        onSaveProgress(newBoard);

        const isFinishingMove = isBoardComplete(newBoard);
        if (!newBoard[r][c].isError && !isFinishingMove) {
            const completedSections = checkSectionCompletion(newBoard, solvedBoard, r, c);
            if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
        }

        const startTime = performance.now();
        const duration = 300; 
        const animate = (time: number) => {
            const elapsed = time - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const currentVal = Math.floor(1 + (val - 1) * progress);
            setAnimatingCell({ r, c, value: currentVal });
            if (progress < 1) requestAnimationFrame(animate);
            else setAnimatingCell(null);
        };
        requestAnimationFrame(animate);
        checkCompletion(newBoard);
    };

    const handleScan = (isPaused: boolean, isCompleted: boolean) => {
        if (scanUses <= 0 || isScanning || scanCooldown || isPaused || isCompleted || revealingCell) return;
        setIsScanning(true);
        setScanCooldown(true);
        sounds.playScan();
        setTimeout(() => {
            const newBoard = board.map(row => row.map(cell => {
                if (!cell.isFixed && cell.value !== null) {
                    const isCorrect = cell.value === solvedBoard[cell.row][cell.col];
                    if (!isCorrect) return { ...cell, isMarkedWrong: true };
                }
                return cell;
            }));
            setBoard(newBoard);
            setIsScanning(false);
            setScanUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, next);
                return next;
            });
            setScanCooldown(false);
        }, 1200); 
    };

    const handleReveal = (isPaused: boolean, isCompleted: boolean) => {
        if (isPaused || isCompleted || revealingCell || isScanning) return;
        if (revealUses <= 0) {
            sounds.playClick();
            return;
        }

        const eligible = [];
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value === null && !cell.isFixed && !cell.isRevealed) {
                    eligible.push({r, c});
                }
            }
        }
        if (eligible.length === 0) return;

        sounds.playReveal(); 
        const target = eligible[Math.floor(Math.random() * eligible.length)];
        setRevealingCell(target);

        setTimeout(() => {
            setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
            const newBoard = board.map(row => [...row]);
            const correctVal = solvedBoard[target.r][target.c];

            newBoard[target.r][target.c] = {
                ...newBoard[target.r][target.c],
                value: correctVal as CellValue,
                notes: [],
                isFixed: false, 
                isRevealed: true, 
                isError: false,
                isMarkedWrong: false
            };

            moveLog.current.push({ r: target.r, c: target.c, v: correctVal, t: Date.now() });

            if (settings.autoEraseNotes) {
                 removeNotesFromPeers(newBoard, target.r, target.c, correctVal);
            }

            setBoard(newBoard);
            setRevealUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, undefined, next);
                return next;
            });

            const isFinishingMove = isBoardComplete(newBoard);
            if (!isFinishingMove) {
                const completedSections = checkSectionCompletion(newBoard, solvedBoard, target.r, target.c);
                if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
            }

            setTimeout(() => {
                setRevealingCell(null);
                checkCompletion(newBoard);
            }, 300); 
        }, 500); 
    };

    const dismissFocus = useCallback(() => {
        setFocusCell(prev => {
            if (!prev || prev.isFading) return prev;
            return { ...prev, isFading: true };
        });

        if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);

        if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);
        fadeTimeoutRef.current = setTimeout(() => {
            setFocusCell(null);
        }, 1000); // 1s fade out duration
    }, []);

    const handleFocus = (isPaused: boolean, isCompleted: boolean) => {
        // Block if cooldown is active, but don't show UI feedback (invisible cooldown)
        if (focusUses <= 0 || isPaused || isCompleted || focusCell || focusCooldown) return;

        // Check for hidden errors (Hard modes)
        const isHard = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;

        // Find if there are any errors on board (value != solved, and not marked as error)
        let hasHiddenErrors = false;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value !== null && cell.value !== solvedBoard[r][c] && !cell.isError && !cell.isMarkedWrong) {
                    hasHiddenErrors = true;
                    break;
                }
            }
            if (hasHiddenErrors) break;
        }

        if (isHard && hasHiddenErrors) {
            setFocusError("You should probably use a Scan...");
            setTimeout(() => setFocusError(null), 3000);
            return;
        }

        // Find logical hint
        const hint = getLogicalHint(board);
        if (hint) {
            sounds.playTap(); // Subtle sound

            // Clear existing timers
            if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);
            if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);

            setFocusCell({ r: hint.r, c: hint.c, isFading: false });

            setFocusUses(prev => {
                const next = prev - 1;
                onSaveProgress(board, undefined, undefined, next);
                return next;
            });

            // Set Invisible Cooldown (10s)
            setFocusCooldown(true);
            setTimeout(() => setFocusCooldown(false), 10000);

            // Auto dismiss after 10s (Effect duration)
            focusTimeoutRef.current = setTimeout(() => {
                dismissFocus();
            }, 10000);
        } else {
            setFocusError("No logical moves found.");
            setTimeout(() => setFocusError(null), 2000);
        }
    };

    return {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        focusUses,
        setFocusUses,
        focusCell,
        setFocusCell,
        focusError,
        handleAutoFill,
        handleScan,
        handleReveal,
        handleFocus,
        dismissFocus // Exposed for click handler
    };
};

import React from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    focusCell?: {r: number, c: number, isFading: boolean} | null; // Updated prop type
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = ({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    focusCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    const getCellClass = (cell: Cell, r: number, c: number) => {
        let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
        const isConflict = conflicts.has(`${r}-${c}`);
        const isError = cell.isError;
        const isMarkedWrong = cell.isMarkedWrong;
        const isRevealed = cell.isRevealed;

        // Focus Logic
        const isFocused = focusCell?.r === r && focusCell?.c === c;

        const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;

        let isSameValue = false;
        if (settings.digitFirst) {
            if (activeNumber !== null) {
                isSameValue = cell.value === activeNumber;
            } else if (selectedCell && cell.value !== null) {
                 isSameValue = board[selectedCell[0]][selectedCell[1]].value === cell.value;
            }
        } else {
            isSameValue = selectedCell && cell.value !== null && board[selectedCell[0]][selectedCell[1]].value === cell.value;
        }

        const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

        let bgClass = ''; 
        const isThisCellRevealing = revealingCell?.r === r && revealingCell?.c === c;

        if (isThisCellRevealing) {
            bgClass = ''; 
        } else if (isMarkedWrong) {
             bgClass = 'bg-red-200 animate-pulse '; 
        } else if (isError || isConflict) {
             bgClass = 'bg-red-50 ';
        } else if (isSelected) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isSameValue) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isRelated) {
             bgClass = 'bg-stone-200/60 dark:bg-stone-100/50 '; 
        } else if (isRevealed) {
             bgClass = 'bg-amber-100 '; 
        } else {
             bgClass = 'bg-t-board '; 
        }

        classes += bgClass;

        if (isSelected && (isError || isConflict || isMarkedWrong)) {
            classes += "ring-2 ring-inset ring-red-400 z-10 ";
        }

        if (isThisCellRevealing) {
            classes += "animate-reveal-premium z-50 relative ";
        }

        if (isFocused) {
            // New Focus Style: Filled Cell, Pulsing, with fade-out support
            classes += "z-40 ring-inset ring-2 ring-teal-400 "; 
        }

        if (cell.isFixed) {
            classes += "font-semibold text-stone-800 ";
        } else if (isRevealed) {
            classes += "font-semibold text-stone-800 ";
        } else {
            if (isError || isConflict || isMarkedWrong) {
                classes += "font-medium text-red-500 ";
            } else {
                classes += "font-medium ";
            }
        }
        return classes;
    };

    const getSectionOverlayStyle = (sectionId: string) => {
        if (sectionId === 'full-board') {
            return {
                position: 'absolute' as const,
                pointerEvents: 'none' as const,
                zIndex: 60,
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                borderWidth: '8px' // Make completion border more prominent
            };
        }

        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 60 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-[10px]">
            <div className="bg-t-board border-2 border-stone-800 rounded-lg overflow-hidden relative flex-none shadow-lg" style={{ width: squareSize, height: squareSize, maxWidth: '500px', maxHeight: '500px' }}>

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;
                    const isFocused = focusCell?.r === rIndex && focusCell?.c === cIndex;
                    const isFocusFading = isFocused && focusCell?.isFading;

                    return (
                        <div 
                            key={`${rIndex}-${cIndex}`} 
                            className={getCellClass(cell, rIndex, cIndex)} 
                            onClick={(e) => {
                                e.stopPropagation();
                                onCellClick(e, rIndex, cIndex);
                            }} 
                            style={{ fontSize: mainFontSize }}
                        >
                        {/* Focus Overlay - Rendered inside to overlay background but sit behind text if needed, or mix */}
                        {isFocused && (
                            <div 
                                className={`absolute inset-0 bg-teal-400/40 animate-pulse pointer-events-none transition-opacity duration-1000 ${isFocusFading ? 'opacity-0' : 'opacity-100'}`} 
                            />
                        )}

                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] relative z-10 ${!cell.isFixed && !cell.isError && !cell.isMarkedWrong && !cell.isRevealed ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none relative z-10">
                                {[1,2,3,4,5,6,7,8,9].map(n => (
                                    <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                        <span className={cell.notes.includes(n) ? 'text-stone-500' : 'invisible'}>{n}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>

            {/* Section/Board Completion Borders */}
            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className={`absolute box-border border-emerald-300 shadow-[0_0_30px_rgba(16,185,129,0.9)] animate-section-complete ${sectionId === 'full-board' ? 'rounded-lg border-4' : 'rounded-sm border-2'}`}
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number, focusUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses,
          focusUses: focusUsesVal !== undefined ? focusUsesVal : focusUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses,
          focusUses
      });

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation (might not have gesture context here if async, but handled gracefully)
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      focusUses,
      setFocusUses,
      focusCell,
      focusError,
      handleAutoFill,
      handleScan,
      handleReveal,
      handleFocus,
      dismissFocus
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r, f) => saveProgress(b, s, r, f),
      onSectionComplete: handleSectionComplete
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
      if (savedProgress.focusUses !== undefined) setFocusUses(savedProgress.focusUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
      setFocusUses(3);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves (e.g. reload), reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            // Row-by-row fill
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `Oku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Oku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setFocusUses(3);
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleDebugWin = () => {
      const newBoard: Board = board.map((row, r) => 
          row.map((cell, c) => ({
              ...cell,
              value: solvedBoard[r][c] as any,
              notes: [],
              isError: false
          }))
      );
      setBoard(newBoard);
      handleGameComplete(newBoard);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  // Determine if erase is possible for the selected cell (value or notes)
  const canErase = !!selectedCell && (() => {
      const [r, c] = selectedCell;
      const cell = board[r][c];
      return !cell.isFixed && (cell.value !== null || cell.notes.length > 0);
  })();

  const onCellClickWrapper = (e: React.MouseEvent, r: number, c: number) => {
      // Check if clicking on the focused cell to dismiss it
      if (focusCell && focusCell.r === r && focusCell.c === c && !focusCell.isFading) {
          dismissFocus();
      }
      handleCellClick(r, c, isPaused, isCompleted);
  };

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-[70px] pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-t-secondary uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <SudokuGrid 
             board={board}
             selectedCell={selectedCell}
             activeNumber={activeNumber}
             conflicts={conflicts}
             revealingCell={revealingCell}
             animatingCell={animatingCell}
             focusCell={focusCell}
             isScanning={isScanning}
             animatingSections={animatingSections}
             settings={settings}
             numberColor={numberColor}
             onCellClick={onCellClickWrapper}
         />

         <div className="w-full max-w-md px-6 mt-4 flex flex-col gap-6" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={canErase}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 focusUses={focusUses}
                 focusError={focusError}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
                 onFocus={() => handleFocus(isPaused, isCompleted)}
             />

             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={(e, n) => handleNumberInput(n, isPaused, isCompleted)}
             />
         </div>

         <div className={`mt-5 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-sm font-light text-stone-400 dark:text-stone-500 tracking-wide">TAP HERE TO DESELECT</span>
         </div>

         <button 
             onClick={(e) => { e.stopPropagation(); handleDebugWin(); }}
             className="mb-6 px-6 py-3 bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-red-200 dark:hover:bg-red-900/50 transition-colors"
         >
             Auto Solve (Debug)
         </button>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import React, { useState, useMemo, SetStateAction, Dispatch, useCallback, useRef, useEffect } from 'react';
import { Board, Difficulty, CellValue, AppSettings } from '../types';
import { sounds } from '../utils/sound';
import { getLogicalHint } from '../utils/sudoku';

interface UseGameSkillsProps {
    board: Board;
    setBoard: Dispatch<SetStateAction<Board>>;
    solvedBoard: number[][];
    setHistory: Dispatch<SetStateAction<Board[]>>;
    moveLog: React.MutableRefObject<{r: number, c: number, v: number, t: number}[]>;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    settings: AppSettings;
    difficulty: Difficulty;
    removeNotesFromPeers: (board: Board, r: number, c: number, val: number) => void;
    checkCompletion: (board: Board) => void;
    onSaveProgress: (board: Board, scanUses?: number, revealUses?: number, focusUses?: number) => void;
    onSectionComplete?: (sections: string[]) => void;
}

const checkSectionCompletion = (board: Board, solvedBoard: number[][], r: number, c: number) => {
    const sections: string[] = [];
    // Row
    if (board[r].every((cell, idx) => cell.value === solvedBoard[r][idx])) sections.push(`row-${r}`);
    // Col
    if (board.every((row, idx) => row[c].value === solvedBoard[idx][c])) sections.push(`col-${c}`);
    // Box
    const startR = Math.floor(r/3)*3;
    const startC = Math.floor(c/3)*3;
    const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
    let boxOk = true;
    for(let i=0; i<3; i++) {
        for(let j=0; j<3; j++) {
            if(board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) {
                boxOk = false;
                break;
            }
        }
    }
    if (boxOk) sections.push(`box-${boxIdx}`);
    return sections;
};

export const useGameSkills = ({
    board,
    setBoard,
    solvedBoard,
    setHistory,
    moveLog,
    selectedCell,
    activeNumber,
    settings,
    difficulty,
    removeNotesFromPeers,
    checkCompletion,
    onSaveProgress,
    onSectionComplete
}: UseGameSkillsProps) => {

    const [scanUses, setScanUses] = useState(3);
    const [isScanning, setIsScanning] = useState(false);
    const [scanCooldown, setScanCooldown] = useState(false);

    const [revealUses, setRevealUses] = useState(1);
    const [revealingCell, setRevealingCell] = useState<{r: number, c: number} | null>(null);

    const [focusUses, setFocusUses] = useState(3);
    const [focusCell, setFocusCell] = useState<{r: number, c: number, isFading: boolean} | null>(null);
    const [focusError, setFocusError] = useState<string | null>(null);

    // Internal cooldown state for Focus (invisible to user UI)
    const [focusCooldown, setFocusCooldown] = useState(false);

    const focusTimeoutRef = useRef<any>(null);
    const fadeTimeoutRef = useRef<any>(null);
    const focusErrorTimeoutRef = useRef<any>(null);

    const [animatingCell, setAnimatingCell] = useState<{r: number, c: number, value: number} | null>(null);

    // Cleanup timers on unmount
    useEffect(() => {
        return () => {
            if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);
            if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
        };
    }, []);

    const isBoardComplete = useCallback((currentBoard: Board) => {
        if (solvedBoard.length === 0) return false;
        let filled = 0;
        let correct = 0;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                if (currentBoard[r][c].value !== null) {
                    filled++;
                    if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
                }
            }
        }
        return filled === 81 && correct === 81;
    }, [solvedBoard]);

    const isAutoAvailable = useMemo(() => {
        if (!selectedCell || board.length === 0) return false;
        let r = selectedCell[0];
        let c = selectedCell[1];
        const cell = board[r][c];
        if (cell.value !== null || cell.isRevealed) return false;

        let rowCount = 0;
        for(let i=0; i<9; i++) if (board[r][i].value !== null) rowCount++;
        if (rowCount === 8) return true;

        let colCount = 0;
        for(let i=0; i<9; i++) if (board[i][c].value !== null) colCount++;
        if (colCount === 8) return true;

        let boxCount = 0;
        const startR = Math.floor(r/3)*3;
        const startC = Math.floor(c/3)*3;
        for(let i=0; i<3; i++)
            for(let j=0; j<3; j++)
                if (board[startR+i][startC+j].value !== null) boxCount++;
        if (boxCount === 8) return true;

        return false;
    }, [board, selectedCell]);

    const handleAutoFill = (purchasedSkills: string[]) => {
        if (!purchasedSkills.includes('skill-auto') || !isAutoAvailable || !selectedCell || isScanning || revealingCell) return;
        sounds.playZap(); 
        const [r, c] = selectedCell;

        let valToFill: number | null = null;

        const getMissing = (values: (number | null)[]) => {
            const vals = new Set(values.filter(v => v !== null));
            for (let i = 1; i <= 9; i++) if (!vals.has(i)) return i;
            return null;
        };

        if (board[r].filter(cell => cell.value !== null).length === 8) {
            valToFill = getMissing(board[r].map(c => c.value));
        }
        if (valToFill === null) {
            const colVals = board.map(row => row[c].value);
            if (colVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(colVals);
            }
        }
        if (valToFill === null) {
            const startR = Math.floor(r/3)*3;
            const startC = Math.floor(c/3)*3;
            const boxVals = [];
            for(let i=0; i<3; i++) for(let j=0; j<3; j++) boxVals.push(board[startR+i][startC+j].value);
            if (boxVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(boxVals);
            }
        }

        if (valToFill === null) valToFill = solvedBoard[r][c];

        const val = valToFill as number;
        setAnimatingCell({ r, c, value: 1 });
        setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
        const newBoard = board.map(row => [...row]);

        const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        const isCorrect = val === solvedBoard[r][c];

        newBoard[r][c] = {
            ...newBoard[r][c],
            value: val as any,
            notes: [],
            isError: !isHarderDifficulty ? !isCorrect : false,
            isMarkedWrong: false
        };

        moveLog.current.push({ r, c, v: val, t: Date.now() });

        if (settings.autoEraseNotes) {
             removeNotesFromPeers(newBoard, r, c, val);
        }

        setBoard(newBoard);
        onSaveProgress(newBoard);

        const isFinishingMove = isBoardComplete(newBoard);
        if (!newBoard[r][c].isError && !isFinishingMove) {
            const completedSections = checkSectionCompletion(newBoard, solvedBoard, r, c);
            if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
        }

        const startTime = performance.now();
        const duration = 300; 
        const animate = (time: number) => {
            const elapsed = time - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const currentVal = Math.floor(1 + (val - 1) * progress);
            setAnimatingCell({ r, c, value: currentVal });
            if (progress < 1) requestAnimationFrame(animate);
            else setAnimatingCell(null);
        };
        requestAnimationFrame(animate);
        checkCompletion(newBoard);
    };

    const handleScan = (isPaused: boolean, isCompleted: boolean) => {
        if (scanUses <= 0 || isScanning || scanCooldown || isPaused || isCompleted || revealingCell) return;
        setIsScanning(true);
        setScanCooldown(true);
        sounds.playScan();
        setTimeout(() => {
            const newBoard = board.map(row => row.map(cell => {
                if (!cell.isFixed && cell.value !== null) {
                    const isCorrect = cell.value === solvedBoard[cell.row][cell.col];
                    if (!isCorrect) return { ...cell, isMarkedWrong: true };
                }
                return cell;
            }));
            setBoard(newBoard);
            setIsScanning(false);
            setScanUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, next);
                return next;
            });
            setScanCooldown(false);
        }, 1200); 
    };

    const handleReveal = (isPaused: boolean, isCompleted: boolean) => {
        if (isPaused || isCompleted || revealingCell || isScanning) return;
        if (revealUses <= 0) {
            sounds.playClick();
            return;
        }

        const eligible = [];
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value === null && !cell.isFixed && !cell.isRevealed) {
                    eligible.push({r, c});
                }
            }
        }
        if (eligible.length === 0) return;

        sounds.playReveal(); 
        const target = eligible[Math.floor(Math.random() * eligible.length)];
        setRevealingCell(target);

        setTimeout(() => {
            setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
            const newBoard = board.map(row => [...row]);
            const correctVal = solvedBoard[target.r][target.c];

            newBoard[target.r][target.c] = {
                ...newBoard[target.r][target.c],
                value: correctVal as CellValue,
                notes: [],
                isFixed: false, 
                isRevealed: true, 
                isError: false,
                isMarkedWrong: false
            };

            moveLog.current.push({ r: target.r, c: target.c, v: correctVal, t: Date.now() });

            if (settings.autoEraseNotes) {
                 removeNotesFromPeers(newBoard, target.r, target.c, correctVal);
            }

            setBoard(newBoard);
            setRevealUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, undefined, next);
                return next;
            });

            const isFinishingMove = isBoardComplete(newBoard);
            if (!isFinishingMove) {
                const completedSections = checkSectionCompletion(newBoard, solvedBoard, target.r, target.c);
                if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
            }

            setTimeout(() => {
                setRevealingCell(null);
                checkCompletion(newBoard);
            }, 300); 
        }, 500); 
    };

    const dismissFocus = useCallback(() => {
        setFocusCell(prev => {
            if (!prev || prev.isFading) return prev;
            return { ...prev, isFading: true };
        });

        if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);

        if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);
        fadeTimeoutRef.current = setTimeout(() => {
            setFocusCell(null);
        }, 1000); // 1s fade out duration
    }, []);

    const dismissFocusError = useCallback(() => {
        setFocusError(null);
        if (focusErrorTimeoutRef.current) {
            clearTimeout(focusErrorTimeoutRef.current);
            focusErrorTimeoutRef.current = null;
        }
    }, []);

    const handleFocus = (isPaused: boolean, isCompleted: boolean) => {
        // Block if cooldown is active, but don't show UI feedback (invisible cooldown)
        if (focusUses <= 0 || isPaused || isCompleted || focusCell || focusCooldown) return;

        // Check for hidden errors (Hard modes)
        const isHard = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;

        // Find if there are any errors on board (value != solved, and not marked as error)
        let hasHiddenErrors = false;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value !== null && cell.value !== solvedBoard[r][c] && !cell.isError && !cell.isMarkedWrong) {
                    hasHiddenErrors = true;
                    break;
                }
            }
            if (hasHiddenErrors) break;
        }

        if (isHard && hasHiddenErrors) {
            setFocusError("You should probably use a Scan...");
            // Reset existing timer if any
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
            // Set new timer
            focusErrorTimeoutRef.current = setTimeout(() => setFocusError(null), 3000);
            return;
        }

        // Find logical hint
        const hint = getLogicalHint(board);
        if (hint) {
            sounds.playTap(); // Subtle sound

            // Clear existing timers
            if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);
            if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);

            setFocusCell({ r: hint.r, c: hint.c, isFading: false });

            setFocusUses(prev => {
                const next = prev - 1;
                onSaveProgress(board, undefined, undefined, next);
                return next;
            });

            // Set Invisible Cooldown (10s)
            setFocusCooldown(true);
            setTimeout(() => setFocusCooldown(false), 10000);

            // Auto dismiss after 10s (Effect duration)
            focusTimeoutRef.current = setTimeout(() => {
                dismissFocus();
            }, 10000);
        } else {
            setFocusError("No logical moves found.");
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
            focusErrorTimeoutRef.current = setTimeout(() => setFocusError(null), 2000);
        }
    };

    return {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        focusUses,
        setFocusUses,
        focusCell,
        setFocusCell,
        focusError,
        handleAutoFill,
        handleScan,
        handleReveal,
        handleFocus,
        dismissFocus, // Exposed for click handler
        dismissFocusError // Exposed for click handler
    };
};

import React from 'react';
import { Icons } from '../ui/Icons';
