export function formatTimeShort(totalSeconds: number) {
    const total = Math.floor(totalSeconds);
    const mins = Math.floor(total / 60);
    const secs = total % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

import React, { useState, useMemo, SetStateAction, Dispatch, useCallback, useRef, useEffect } from 'react';
import { Board, Difficulty, CellValue, AppSettings } from '../types';
