interface UseGameSkillsProps {
    board: Board;
    setBoard: Dispatch<SetStateAction<Board>>;
    solvedBoard: number[][];
    setHistory: Dispatch<SetStateAction<Board[]>>;
    moveLog: React.MutableRefObject<{r: number, c: number, v: number, t: number}[]>;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    settings: AppSettings;
    difficulty: Difficulty;
    removeNotesFromPeers: (board: Board, r: number, c: number, val: number) => void;
    checkCompletion: (board: Board) => void;
    onSaveProgress: (board: Board, scanUses?: number, revealUses?: number, focusUses?: number) => void;
    onSectionComplete?: (sections: string[]) => void;
    timer: number;
}

const checkSectionCompletion = (board: Board, solvedBoard: number[][], r: number, c: number) => {
    const sections: string[] = [];
    // Row
    if (board[r].every((cell, idx) => cell.value === solvedBoard[r][idx])) sections.push(`row-${r}`);
    // Col
    if (board.every((row, idx) => row[c].value === solvedBoard[idx][c])) sections.push(`col-${c}`);
    // Box
    const startR = Math.floor(r/3)*3;
    const startC = Math.floor(c/3)*3;
    const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
    let boxOk = true;
    for(let i=0; i<3; i++) {
        for(let j=0; j<3; j++) {
            if(board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) {
                boxOk = false;
                break;
            }
        }
    }
    if (boxOk) sections.push(`box-${boxIdx}`);
    return sections;
};

export const useGameSkills = ({
    board,
    setBoard,
    solvedBoard,
    setHistory,
    moveLog,
    selectedCell,
    activeNumber,
    settings,
    difficulty,
    removeNotesFromPeers,
    checkCompletion,
    onSaveProgress,
    onSectionComplete,
    timer
}: UseGameSkillsProps) => {

    const [scanUses, setScanUses] = useState(3);
    const [isScanning, setIsScanning] = useState(false);
    const [scanCooldown, setScanCooldown] = useState(false);

    const [revealUses, setRevealUses] = useState(1);
    const [revealingCell, setRevealingCell] = useState<{r: number, c: number} | null>(null);

    const [focusUses, setFocusUses] = useState(3);
    const [focusCell, setFocusCell] = useState<{r: number, c: number, isFading: boolean} | null>(null);
    const [focusError, setFocusError] = useState<{ text: string, isFading: boolean } | null>(null);

    // Internal cooldown state for Focus (invisible to user UI)
    const [focusCooldown, setFocusCooldown] = useState(false);

    const focusTimeoutRef = useRef<any>(null);
    const fadeTimeoutRef = useRef<any>(null);
    const focusErrorTimeoutRef = useRef<any>(null);

    const [animatingCell, setAnimatingCell] = useState<{r: number, c: number, value: number} | null>(null);

    // Cleanup timers on unmount
    useEffect(() => {
        return () => {
            if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);
            if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
        };
    }, []);

    const isBoardComplete = useCallback((currentBoard: Board) => {
        if (solvedBoard.length === 0) return false;
        let filled = 0;
        let correct = 0;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                if (currentBoard[r][c].value !== null) {
                    filled++;
                    if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
                }
            }
        }
        return filled === 81 && correct === 81;
    }, [solvedBoard]);

    const isAutoAvailable = useMemo(() => {
        if (!selectedCell || board.length === 0) return false;
        let r = selectedCell[0];
        let c = selectedCell[1];
        const cell = board[r][c];
        if (cell.value !== null || cell.isRevealed) return false;

        let rowCount = 0;
        for(let i=0; i<9; i++) if (board[r][i].value !== null) rowCount++;
        if (rowCount === 8) return true;

        let colCount = 0;
        for(let i=0; i<9; i++) if (board[i][c].value !== null) colCount++;
        if (colCount === 8) return true;

        let boxCount = 0;
        const startR = Math.floor(r/3)*3;
        const startC = Math.floor(c/3)*3;
        for(let i=0; i<3; i++)
            for(let j=0; j<3; j++)
                if (board[startR+i][startC+j].value !== null) boxCount++;
        if (boxCount === 8) return true;

        return false;
    }, [board, selectedCell]);

    const handleAutoFill = (purchasedSkills: string[]) => {
        if (!purchasedSkills.includes('skill-auto') || !isAutoAvailable || !selectedCell || isScanning || revealingCell) return;
        sounds.playZap(); 
        const [r, c] = selectedCell;

        let valToFill: number | null = null;

        const getMissing = (values: (number | null)[]) => {
            const vals = new Set(values.filter(v => v !== null));
            for (let i = 1; i <= 9; i++) if (!vals.has(i)) return i;
            return null;
        };

        if (board[r].filter(cell => cell.value !== null).length === 8) {
            valToFill = getMissing(board[r].map(c => c.value));
        }
        if (valToFill === null) {
            const colVals = board.map(row => row[c].value);
            if (colVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(colVals);
            }
        }
        if (valToFill === null) {
            const startR = Math.floor(r/3)*3;
            const startC = Math.floor(c/3)*3;
            const boxVals = [];
            for(let i=0; i<3; i++) for(let j=0; j<3; j++) boxVals.push(board[startR+i][startC+j].value);
            if (boxVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(boxVals);
            }
        }

        if (valToFill === null) valToFill = solvedBoard[r][c];

        const val = valToFill as number;
        setAnimatingCell({ r, c, value: 1 });
        setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
        const newBoard = board.map(row => [...row]);

        const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        const isCorrect = val === solvedBoard[r][c];

        newBoard[r][c] = {
            ...newBoard[r][c],
            value: val as any,
            notes: [],
            isError: !isHarderDifficulty ? !isCorrect : false,
            isMarkedWrong: false
        };

        moveLog.current.push({ r, c, v: val, t: Date.now() });

        if (settings.autoEraseNotes) {
             removeNotesFromPeers(newBoard, r, c, val);
        }

        setBoard(newBoard);
        onSaveProgress(newBoard);

        const isFinishingMove = isBoardComplete(newBoard);
        if (!newBoard[r][c].isError && !isFinishingMove) {
            const completedSections = checkSectionCompletion(newBoard, solvedBoard, r, c);
            if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
        }

        const startTime = performance.now();
        const duration = 300; 
        const animate = (time: number) => {
            const elapsed = time - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const currentVal = Math.floor(1 + (val - 1) * progress);
            setAnimatingCell({ r, c, value: currentVal });
            if (progress < 1) requestAnimationFrame(animate);
            else setAnimatingCell(null);
        };
        requestAnimationFrame(animate);
        checkCompletion(newBoard);
    };

    const handleScan = (isPaused: boolean, isCompleted: boolean) => {
        if (scanUses <= 0 || isScanning || scanCooldown || isPaused || isCompleted || revealingCell) return;
        setIsScanning(true);
        setScanCooldown(true);
        sounds.playScan();
        setTimeout(() => {
            const newBoard = board.map(row => row.map(cell => {
                if (!cell.isFixed && cell.value !== null) {
                    const isCorrect = cell.value === solvedBoard[cell.row][cell.col];
                    if (!isCorrect) return { ...cell, isMarkedWrong: true };
                }
                return cell;
            }));
            setBoard(newBoard);
            setIsScanning(false);
            setScanUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, next);
                return next;
            });
            setScanCooldown(false);
        }, 1200); 
    };

    const handleReveal = (isPaused: boolean, isCompleted: boolean) => {
        if (isPaused || isCompleted || revealingCell || isScanning) return;

        // 1 Minute Restriction for Reveal
        if (timer < 60) {
            sounds.playClick();
            return;
        }

        if (revealUses <= 0) {
            sounds.playClick();
            return;
        }

        const eligible = [];
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value === null && !cell.isFixed && !cell.isRevealed) {
                    eligible.push({r, c});
                }
            }
        }
        if (eligible.length === 0) return;

        sounds.playReveal(); 
        const target = eligible[Math.floor(Math.random() * eligible.length)];
        setRevealingCell(target);

        setTimeout(() => {
            setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
            const newBoard = board.map(row => [...row]);
            const correctVal = solvedBoard[target.r][target.c];

            newBoard[target.r][target.c] = {
                ...newBoard[target.r][target.c],
                value: correctVal as CellValue,
                notes: [],
                isFixed: false, 
                isRevealed: true, 
                isError: false,
                isMarkedWrong: false
            };

            moveLog.current.push({ r: target.r, c: target.c, v: correctVal, t: Date.now() });

            if (settings.autoEraseNotes) {
                 removeNotesFromPeers(newBoard, target.r, target.c, correctVal);
            }

            setBoard(newBoard);
            setRevealUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, undefined, next);
                return next;
            });

            const isFinishingMove = isBoardComplete(newBoard);
            if (!isFinishingMove) {
                const completedSections = checkSectionCompletion(newBoard, solvedBoard, target.r, target.c);
                if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
            }

            setTimeout(() => {
                setRevealingCell(null);
                checkCompletion(newBoard);
            }, 300); 
        }, 500); 
    };

    const dismissFocus = useCallback(() => {
        setFocusCell(prev => {
            if (!prev || prev.isFading) return prev;
            return { ...prev, isFading: true };
        });

        if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);

        if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);
        fadeTimeoutRef.current = setTimeout(() => {
            setFocusCell(null);
        }, 1000); // 1s fade out duration
    }, []);

    const dismissFocusError = useCallback(() => {
        setFocusError(prev => {
            if (!prev || prev.isFading) return prev;
            return { ...prev, isFading: true };
        });

        if (focusErrorTimeoutRef.current) {
            clearTimeout(focusErrorTimeoutRef.current);
            focusErrorTimeoutRef.current = null;
        }

        // Add a timeout to actually remove it after animation
        focusErrorTimeoutRef.current = setTimeout(() => {
            setFocusError(null);
        }, 200); // Matches tooltip-exit duration (approx)
    }, []);

    const handleFocus = (isPaused: boolean, isCompleted: boolean) => {
        // Block if cooldown is active, but don't show UI feedback (invisible cooldown)
        if (focusUses <= 0 || isPaused || isCompleted || focusCell || focusCooldown) return;

        // Find if there are any errors on board
        let hasVisibleErrors = false;
        let hasHiddenErrors = false;

        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value !== null) {
                    const isWrong = cell.value !== solvedBoard[r][c];

                    if (cell.isError || cell.isMarkedWrong) {
                        hasVisibleErrors = true;
                    } else if (isWrong) {
                        hasHiddenErrors = true;
                    }
                }
            }
        }

        // 1. Block if visible errors exist.
        if (hasVisibleErrors) {
            setFocusError({ text: "You should probably use a Scan...", isFading: false });
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
            focusErrorTimeoutRef.current = setTimeout(() => dismissFocusError(), 3000);
            return;
        }

        // 2. Check for hidden errors (Hard modes where auto-check is off)
        const isHard = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;

        if (isHard && hasHiddenErrors) {
            setFocusError({ text: "You should probably use a Scan...", isFading: false });
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
            focusErrorTimeoutRef.current = setTimeout(() => dismissFocusError(), 3000);
            return;
        }

        // Find logical hint
        const hint = getLogicalHint(board);
        if (hint) {
            sounds.playTap(); // Subtle sound

            // Clear existing timers
            if (focusTimeoutRef.current) clearTimeout(focusTimeoutRef.current);
            if (fadeTimeoutRef.current) clearTimeout(fadeTimeoutRef.current);

            setFocusCell({ r: hint.r, c: hint.c, isFading: false });

            setFocusUses(prev => {
                const next = prev - 1;
                onSaveProgress(board, undefined, undefined, next);
                return next;
            });

            // Set Invisible Cooldown (10s)
            setFocusCooldown(true);
            setTimeout(() => setFocusCooldown(false), 10000);

            // Auto dismiss after 10s (Effect duration)
            focusTimeoutRef.current = setTimeout(() => {
                dismissFocus();
            }, 10000);
        } else {
            setFocusError({ text: "No logical moves found.", isFading: false });
            if (focusErrorTimeoutRef.current) clearTimeout(focusErrorTimeoutRef.current);
            focusErrorTimeoutRef.current = setTimeout(() => dismissFocusError(), 2000);
        }
    };

    return {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        focusUses,
        setFocusUses,
        focusCell,
        setFocusCell,
        focusError,
        handleAutoFill,
        handleScan,
        handleReveal,
        handleFocus,
        dismissFocus, // Exposed for click handler
        dismissFocusError // Exposed for click handler
    };
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number, focusUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses,
          focusUses: focusUsesVal !== undefined ? focusUsesVal : focusUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses,
          focusUses
      });

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation (might not have gesture context here if async, but handled gracefully)
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      focusUses,
      setFocusUses,
      focusCell,
      focusError,
      handleAutoFill,
      handleScan,
      handleReveal,
      handleFocus,
      dismissFocus,
      dismissFocusError
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r, f) => saveProgress(b, s, r, f),
      onSectionComplete: handleSectionComplete,
      timer
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
      if (savedProgress.focusUses !== undefined) setFocusUses(savedProgress.focusUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
      setFocusUses(3);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves (e.g. reload), reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            // Row-by-row fill
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `Oku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Oku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setFocusUses(3);
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleDebugWin = () => {
      const newBoard: Board = board.map((row, r) => 
          row.map((cell, c) => ({
              ...cell,
              value: solvedBoard[r][c] as any,
              notes: [],
              isError: false
          }))
      );
      setBoard(newBoard);
      handleGameComplete(newBoard);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      // Dismiss error on background tap
      dismissFocusError();
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  // Determine if erase is possible for the selected cell (value or notes)
  const canErase = !!selectedCell && (() => {
      const [r, c] = selectedCell;
      const cell = board[r][c];
      return !cell.isFixed && (cell.value !== null || cell.notes.length > 0);
  })();

  const onCellClickWrapper = (e: React.MouseEvent, r: number, c: number) => {
      // Dismiss error on cell tap
      dismissFocusError();
      // Check if clicking on the focused cell to dismiss it
      if (focusCell && focusCell.r === r && focusCell.c === c && !focusCell.isFading) {
          dismissFocus();
      }
      handleCellClick(r, c, isPaused, isCompleted);
  };

  const onNumberClickWrapper = (e: React.MouseEvent, n: number) => {
      // Dismiss error on number pad tap
      dismissFocusError();
      handleNumberInput(n, isPaused, isCompleted);
  };

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-[70px] pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-t-secondary uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <SudokuGrid 
             board={board}
             selectedCell={selectedCell}
             activeNumber={activeNumber}
             conflicts={conflicts}
             revealingCell={revealingCell}
             animatingCell={animatingCell}
             focusCell={focusCell}
             isScanning={isScanning}
             animatingSections={animatingSections}
             settings={settings}
             numberColor={numberColor}
             onCellClick={onCellClickWrapper}
         />

         {/* Added relative z-[100] to ensure controls (and tooltips) sit above the grid (z-50) */}
         <div className="w-full max-w-md px-6 mt-4 flex flex-col gap-6 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={canErase}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 focusUses={focusUses}
                 focusError={focusError}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
                 onFocus={() => handleFocus(isPaused, isCompleted)}
                 timer={timer}
             />

             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={onNumberClickWrapper}
             />
         </div>

         <div className={`mt-5 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-sm font-light text-stone-400 dark:text-stone-500 tracking-wide">TAP HERE TO DESELECT</span>
         </div>

         <button 
             onClick={(e) => { e.stopPropagation(); handleDebugWin(); }}
             className="mb-6 px-6 py-3 bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-red-200 dark:hover:bg-red-900/50 transition-colors"
         >
             Auto Solve (Debug)
         </button>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import React from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';

interface GameControlsProps {
    canUndo: boolean;
    canErase: boolean;
    isPencilMode: boolean;
    onUndo: (e: React.MouseEvent) => void;
    onErase: (e: React.MouseEvent) => void;
    onTogglePencil: (e: React.MouseEvent) => void;
    purchasedSkills: string[];
    // Skill specific props
    isAutoAvailable: boolean;
    scanUses: number;
    isScanning: boolean;
    scanCooldown: boolean;
    revealUses: number;
    revealingCell: {r: number, c: number} | null;
    focusUses: number;
    focusError?: { text: string; isFading: boolean } | null;
    onAutoFill: (e: React.MouseEvent) => void;
    onScan: (e: React.MouseEvent) => void;
    onReveal: (e: React.MouseEvent) => void;
    onFocus: (e: React.MouseEvent) => void;
    timer: number;
}

export const GameControls: React.FC<GameControlsProps> = ({
    canUndo,
    canErase,
    isPencilMode,
    onUndo,
    onErase,
    onTogglePencil,
    purchasedSkills,
    isAutoAvailable,
    scanUses,
    isScanning,
    scanCooldown,
    revealUses,
    revealingCell,
    focusUses,
    focusError,
    onAutoFill,
    onScan,
    onReveal,
    onFocus,
    timer
}) => {
    // Helper for common enabled/disabled styles
    const getBaseButtonStyle = (isEnabled: boolean) => 
        isEnabled 
            ? 'text-stone-900 dark:text-stone-100 cursor-pointer hover:brightness-95 active:scale-95' 
            : 'text-stone-300 dark:text-stone-600 cursor-not-allowed';

    const getBaseContainerStyle = (isEnabled: boolean) => 
        isEnabled
            ? 'bg-white dark:bg-stone-800 border-stone-300 dark:border-stone-600'
            : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700';

    const revealTimeLeft = Math.max(0, 60 - timer);
    const isRevealLocked = revealTimeLeft > 0;

    return (
        <div className="flex justify-between w-full relative">
            {/* Reveal Skill Button */}
            {purchasedSkills.includes('skill-reveal') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onReveal(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(revealUses > 0 && !revealingCell && !isRevealLocked)}`}
                        disabled={!!revealingCell || isRevealLocked}
                    >
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(revealUses > 0 && !isRevealLocked)}`}>
                        {isRevealLocked ? (
                            <div className="w-5 h-5 flex items-center justify-center">
                                <span className="text-[10px] font-bold text-stone-400 font-mono leading-none">{revealTimeLeft}s</span>
                            </div>
                        ) : (
                            <Icons.Reveal className={`w-5 h-5 ${revealUses > 0 ? 'text-purple-600 dark:text-purple-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        )}

                        <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold border-2 border-t-surface leading-none ${revealUses > 0 && !isRevealLocked ? 'bg-blue-600 text-white' : 'bg-stone-300 text-white dark:bg-stone-600'}`}>
                                {revealUses > 0 ? revealUses : '+'}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Reveal</span>
                </button>
            )}

            {/* Scan Skill Button */}
            {purchasedSkills.includes('skill-scan') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onScan(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}
                        disabled={scanUses <= 0 || scanCooldown || isScanning}
                    >
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}>
                        <Icons.Scan className={`w-5 h-5 ${scanUses > 0 && !scanCooldown && !isScanning ? 'text-red-600 dark:text-red-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        {scanUses > 0 && (
                            <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold border-2 border-t-surface leading-none ${scanUses > 0 ? 'bg-blue-600 text-white' : 'hidden'}`}>
                                {scanUses}
                            </div>
                        )}
                    </div>
                    <span className="text-sm font-medium">Scan</span>
                </button>
            )}

            {/* Focus Skill Button */}
            {purchasedSkills.includes('skill-focus') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onFocus(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative group ${getBaseButtonStyle(focusUses > 0)}`}
                        disabled={focusUses <= 0}
                    >
                    {/* Tooltip */}
                    {focusError && (
                        // WRAPPER 1: Handles Positioning (-translate-x-5 for correct arrow alignment on left side)
                        <div className="absolute bottom-full left-1/2 -translate-x-5 mb-3 w-max max-w-[200px] z-[100] pointer-events-none">
                            {/* WRAPPER 2: Handles Animation (scale) */}
                            <div className={focusError.isFading ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}>
                                <div className="bg-white text-stone-900 text-xs font-medium px-4 py-3 rounded-xl relative text-left leading-relaxed border border-stone-400 dark:border-stone-500 shadow-none">
                                    {focusError.text}
                                    {/* Arrow: left-3 aligns with button center due to wrapper shift */}
                                    <div className="absolute -bottom-[6px] left-3 w-3 h-3 bg-white border-b border-r border-stone-400 dark:border-stone-500 transform rotate-45"></div>
                                </div>
                            </div>
                        </div>
                    )}

                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(focusUses > 0)}`}>
                        <Icons.Focus className={`w-5 h-5 ${focusUses > 0 ? 'text-teal-500 dark:text-teal-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        {focusUses > 0 && (
                            <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold border-2 border-t-surface leading-none ${focusUses > 0 ? 'bg-blue-600 text-white' : 'hidden'}`}>
                                {focusUses}
                            </div>
                        )}
                    </div>
                    <span className="text-sm font-medium">Focus</span>
                </button>
            )}

            {/* Auto Skill Button */}
            {purchasedSkills.includes('skill-auto') && (
                <button 
                    onClick={(e) => { e.stopPropagation(); onAutoFill(e); }} 
                    className={`flex flex-col items-center gap-1 transition relative active:scale-95 ${isAutoAvailable ? 'cursor-pointer text-amber-700 dark:text-amber-400' : 'cursor-not-allowed text-stone-300 dark:text-stone-600'}`}
                    disabled={!isAutoAvailable}
                >
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 ${
                        isAutoAvailable 
                        ? 'bg-amber-100 border-amber-300 ring-1 ring-amber-200 dark:bg-amber-900/30 dark:border-amber-700 dark:ring-amber-900/50' 
                        : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
                    </div>
                    <span className="text-sm font-medium">Auto</span>
                </button>
            )}

            {/* UNDO BUTTON */}
            <button 
                onClick={onUndo} 
                disabled={!canUndo}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canUndo)}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${getBaseContainerStyle(canUndo)}`}>
                    <Icons.Undo className={`w-5 h-5 ${canUndo ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Undo</span>
            </button>

            {/* PENCIL BUTTON */}
            <button 
                onClick={onTogglePencil} 
                className={`flex flex-col items-center gap-1 active:scale-95 transition cursor-pointer hover:brightness-95 ${isPencilMode ? 'text-blue-700 dark:text-blue-300' : 'text-stone-900 dark:text-stone-100'}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${
                    isPencilMode 
                    ? 'bg-blue-100 border-blue-400 dark:bg-blue-900/40 dark:border-blue-700' 
                    : 'bg-white dark:bg-stone-800 border-stone-300 dark:border-stone-600'
                }`}>
                    <Icons.Pencil className={`w-5 h-5 ${isPencilMode ? 'text-blue-600 dark:text-blue-400' : 'text-stone-700 dark:text-stone-300'}`} />
                </div>
                <span className="text-sm font-medium">Pencil</span>
            </button>

            {/* ERASE BUTTON */}
            <button 
                onClick={onErase} 
                disabled={!canErase}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canErase)}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${getBaseContainerStyle(canErase)}`}>
                    <Icons.Erase className={`w-5 h-5 ${canErase ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Erase</span>
            </button>
        </div>
    );
};

import React from 'react';
