                        ? 'bg-amber-100 border-amber-300 ring-1 ring-amber-200 dark:bg-amber-900/30 dark:border-amber-700 dark:ring-amber-900/50' 
                        : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
