                                className="bg-gradient-to-b from-blue-50 to-white dark:from-stone-800 dark:to-stone-900 rounded-2xl p-1.5 flex flex-col items-center justify-between shadow-sm border border-blue-100 dark:border-stone-700 h-40 active:scale-95 transition-transform"
