  highlight: boolean;
  autoEraseNotes: boolean; // Default ON
  vibration: boolean;
  showTimer: boolean;
  appearance: 'system' | 'light' | 'dark';
  digitFirst: boolean; // Input mode
  screenWakeLock: boolean; // Keep screen on
  generateReplay: boolean; // Generate video replay on completion
}

